# Cell 2

def get_rna_fold_structure(sequence_str):
    """
    Calls RNAfold to get the MFE secondary structure.
    Input: RNA sequence string (e.g., "AUGCAUGC")
    Output: Dot-bracket structure string (e.g., "((....))") or None if error
    """
    try:
        process = subprocess.Popen(
            ['RNAfold', '--noPS'],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate(input=sequence_str)

        if process.returncode != 0:
            return None

        lines = stdout.strip().split('\n')
        if len(lines) >= 2:
            structure_line = ""
            for line in reversed(lines):
                if '(' in line or ')' in line or '.' in line:
                    structure_line = line
                    break
            if structure_line:
                return structure_line.split(' ')[0]
            return None
        return None
    except FileNotFoundError:
        print("ERROR: RNAfold command not found. Make sure ViennaRNA is installed and in PATH.")
        return None
    except Exception as e:
        return None

test_seq_fold = "GGGAAACCCTTTGGGAAACCC"
structure_fold = get_rna_fold_structure(test_seq_fold)
if structure_fold:
    print(f"RNAfold wrapper test OK. Example: {test_seq_fold} -> {structure_fold}")
