print(f"SEQ_VOCAB_SIZE: {SEQ_VOCAB_SIZE if 'SEQ_VOCAB_SIZE' in globals() else 'Not Defined'}")
print(f"STRUCT_VOCAB_SIZE: {STRUCT_VOCAB_SIZE if 'STRUCT_VOCAB_SIZE' in globals() else 'Not Defined'}")
