# Cell 7: Model Definition

import tensorflow as tf
from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Embedding, Bidirectional, LSTM, Dense, TimeDistributed, Dropout, BatchNormalization
from tensorflow.keras.regularizers import l2 # For L2 regularization

print("--- Defining the RNA Secondary Structure Prediction Model ---")

EMBEDDING_DIM = 128
LSTM_UNITS = 256            # Number of units in the LSTM layer(s)
DROPOUT_RATE = 0.3          # Dropout rate for regularization
LSTM_DROPOUT_RATE = 0.2     # Dropout for LSTM recurrent connections
L2_REG_STRENGTH = 1e-5      # L2 regularization strength for LSTM layers

if 'SEQ_VOCAB_SIZE' not in globals() or \
   'STRUCT_VOCAB_SIZE' not in globals() or \
   'EXPECTED_MAX_LEN' not in globals():
    print("🔴 ERROR: SEQ_VOCAB_SIZE, STRUCT_VOCAB_SIZE, or EXPECTED_MAX_LEN not found in globals.")
    print("   Please ensure Cell 1 (defining these) and the data loading/processing cell have run.")
    if 'SEQ_VOCAB_SIZE' not in globals(): SEQ_VOCAB_SIZE = 5
    if 'STRUCT_VOCAB_SIZE' not in globals(): STRUCT_VOCAB_SIZE = 4
    if 'EXPECTED_MAX_LEN' not in globals(): EXPECTED_MAX_LEN = 150
    print(f"🔴 WARNING: Using fallback vocab/max_len: SEQ_VOCAB_SIZE={SEQ_VOCAB_SIZE}, STRUCT_VOCAB_SIZE={STRUCT_VOCAB_SIZE}, EXPECTED_MAX_LEN={EXPECTED_MAX_LEN}")

model = Sequential(name="RNA_Structure_Predictor")

# 1. Embedding Layer
model.add(Embedding(
    input_dim=SEQ_VOCAB_SIZE,
    output_dim=EMBEDDING_DIM,
    input_length=EXPECTED_MAX_LEN,
    name="embedding_layer"
))

model.add(Dropout(DROPOUT_RATE, name="dropout_embedding"))

# 2. Bidirectional LSTM Layer(s)
model.add(Bidirectional(LSTM(
    units=LSTM_UNITS,
    return_sequences=True,
    dropout=LSTM_DROPOUT_RATE,
    recurrent_dropout=LSTM_DROPOUT_RATE,
    name="bidirectional_lstm_1"
)))

model.add(Dropout(DROPOUT_RATE, name="dropout_lstm1"))

# 3. TimeDistributed Dense Output Layer
model.add(TimeDistributed(Dense(
    units=STRUCT_VOCAB_SIZE,
    activation='softmax',
    name="output_dense_layer"
)))

model.compile(
    optimizer=tf.keras.optimizers.Adam(learning_rate=0.001), # Adam optimizer, can tune learning rate
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

model.build(input_shape=(None, EXPECTED_MAX_LEN))

model.summary()

print("\nModel defined and compiled successfully.")

"""# **TRAINING DATASET 1**"""

print("--- Data Type Check ---")
print(f"X_train_1_split dtype: {X_train_1_split.dtype}, shape: {X_train_1_split.shape}")
print(f"y_train_1_split dtype: {y_train_1_split.dtype}, shape: {y_train_1_split.shape}")
print(f"X_val_1_split dtype: {X_val_1_split.dtype}, shape: {X_val_1_split.shape}")
print(f"y_val_1_split dtype: {y_val_1_split.dtype}, shape: {y_val_1_split.shape}")

# Cell 8 Train the Model
EPOCHS = 50
BATCH_SIZE = 64
from tensorflow.keras.callbacks import ModelCheckpoint, EarlyStopping

checkpoint_filepath = '/content/drive/My Drive/RNA_Project_Models/best_model_dataset1.keras' # Ensure this path exists or can be created
model_checkpoint_callback = ModelCheckpoint(
    filepath=checkpoint_filepath,
    save_weights_only=False,
    monitor='val_loss',
    mode='min',
    save_best_only=True,
    verbose=1
)

early_stopping_callback = EarlyStopping(
    monitor='val_loss',
    patience=5,
    verbose=1,
    restore_best_weights=True
)

print(f"\n--- Starting Model Training for Dataset 1 ---")
print(f"Training with X_train_1_split shape: {X_train_1_split.shape}, y_train_1_split shape: {y_train_1_split.shape}")
print(f"Validation with X_val_1_split shape: {X_val_1_split.shape}, y_val_1_split shape: {y_val_1_split.shape}")

history_1 = model.fit(X_train_1_split,
    y_train_1_split,
    epochs=EPOCHS,
    batch_size=BATCH_SIZE,
    validation_data=(X_val_1_split, y_val_1_split),
    callbacks=[model_checkpoint_callback, early_stopping_callback],
    verbose=1
)

print("\n--- Model Training Finished ---")

plt.plot(history_1.history['accuracy'], label='train_accuracy')
plt.plot(history_1.history['val_accuracy'], label='val_accuracy')
plt.xlabel('Epoch')
plt.ylabel('Accuracy')
plt.legend()
plt.show()

loss, accuracy = model.evaluate(X_test_1_split, y_test_1_split, verbose=0)
print(f"\nTest Loss for Dataset 4: {loss:.4f}")
print(f"Test Accuracy for Dataset 4: {accuracy:.4f}")

