import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay

print(f"--- Evaluating Model for Dataset 1 ---")
MODEL_TO_LOAD_PATH = '/content/drive/MyDrive/RNA_Project_Models/best_model_dataset1.keras' # CHANGE FILENAME FOR OTHER DATASETS
print(f"Loading model from: {MODEL_TO_LOAD_PATH}")
try:
    loaded_model = tf.keras.models.load_model(MODEL_TO_LOAD_PATH)
    print("Model loaded successfully.")
    model_to_evaluate = loaded_model
except Exception as e:
    print(f"🔴 Error loading model: {e}. Will try to use the 'model' variable from training if available.")
    if 'model' in globals():
        print("Using 'model' variable from the current session's training.")
        model_to_evaluate = model
    else:
        print("🔴 ERROR: No model available for evaluation.")
