  from tensorflow.keras.callbacks import ModelCheckpoint, EarlyStopping
  import matplotlib.pyplot as plt
  # --- Training Hyperparameters ---
  EPOCHS = 50
  BATCH_SIZE = 64
  # --- Callbacks
  checkpoint_filepath_ds2 = '/content/drive/My Drive/RNA_Project_Models/best_model_dataset2.keras'
  model_checkpoint_callback_ds2 = ModelCheckpoint(
      filepath=checkpoint_filepath_ds2,
      save_weights_only=False,
      monitor='val_loss',
      mode='min',
      save_best_only=True,
      verbose=1
  )

  early_stopping_callback_ds2 = EarlyStopping(
      monitor='val_loss',
      patience=10,
      verbose=1,
      mode='min',
      restore_best_weights=True
  )

  print(f"\n--- Starting Model Training for Dataset 2 (gc_26_50) ---")
  print(f"Training with X_train_2_split shape: {X_train_2_split.shape}, y_train_2_split shape: {y_train_2_split.shape}")
  print(f"Validation with X_val_2_split shape: {X_val_2_split.shape}, y_val_2_split shape: {y_val_2_split.shape}")

  history_2 = model.fit(
      X_train_2_split,
      y_train_2_split,
      epochs=EPOCHS,
      batch_size=BATCH_SIZE,
      validation_data=(X_val_2_split, y_val_2_split),
      callbacks=[model_checkpoint_callback_ds2, early_stopping_callback_ds2],
      verbose=1
  )

  print("\n--- Model Training Finished for Dataset 2 ---")

  #  Plotting Training History-
  print("\nPlotting training history for Dataset 2...")
  plt.figure(figsize=(12, 4))

  plt.subplot(1, 2, 1)
  plt.plot(history_2.history['loss'], label='Training Loss')
  plt.plot(history_2.history['val_loss'], label='Validation Loss')
  plt.title('Dataset 2: Loss over Epochs')
  plt.xlabel('Epoch')
  plt.ylabel('Loss')
  plt.legend()

  plt.subplot(1, 2, 2)
  plt.plot(history_2.history['accuracy'], label='Training Accuracy')
  plt.plot(history_2.history['val_accuracy'], label='Validation Accuracy')
  plt.title('Dataset 2: Accuracy over Epochs')
  plt.xlabel('Epoch')
  plt.ylabel('Accuracy')
  plt.legend()

  plt.tight_layout()
  plt.show()



