"""# **Model3(V3)-Deeper BiLSTM**"""

# Cell 7: Model Definition (v3 - Deeper BiLSTM)

import tensorflow as tf
from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Embedding, Bidirectional, LSTM, Dense, TimeDistributed, Dropout, BatchNormalization

print("--- Defining the RNA Secondary Structure Prediction Model (v3 - Deeper BiLSTM) ---")

EMBEDDING_DIM = 128
LSTM_UNITS_L1 = 256
LSTM_UNITS_L2 = 128
DROPOUT_RATE_EMBED = 0.3
DROPOUT_RATE_LSTM = 0.3
LSTM_INTERNAL_DROPOUT = 0.2

if 'SEQ_VOCAB_SIZE' not in globals() or \
   'STRUCT_VOCAB_SIZE' not in globals() or \
   'EXPECTED_MAX_LEN' not in globals():
    print("🔴 ERROR: SEQ_VOCAB_SIZE, STRUCT_VOCAB_SIZE, or EXPECTED_MAX_LEN not found in globals.")
    print("   Please ensure Cell 1 (defining these) and the data loading/processing cell have run.")
    SEQ_VOCAB_SIZE = 5
    STRUCT_VOCAB_SIZE = 4
    EXPECTED_MAX_LEN = 150
    print(f"🔴 WARNING: Using fallback vocab/max_len: SEQ_VOCAB_SIZE={SEQ_VOCAB_SIZE}, STRUCT_VOCAB_SIZE={STRUCT_VOCAB_SIZE}, EXPECTED_MAX_LEN={EXPECTED_MAX_LEN}")

model_v3 = Sequential(name="RNA_Structure_Predictor_v3_DeeperBiLSTM")

model_v3.add(Embedding(
    input_dim=SEQ_VOCAB_SIZE,
    output_dim=EMBEDDING_DIM,
    input_length=EXPECTED_MAX_LEN,
    name="embedding_layer"
))
model_v3.add(Dropout(DROPOUT_RATE_EMBED, name="dropout_embedding"))

model_v3.add(Bidirectional(LSTM(
    units=LSTM_UNITS_L1,
    return_sequences=True,
    dropout=LSTM_INTERNAL_DROPOUT,
    recurrent_dropout=LSTM_INTERNAL_DROPOUT,
    name="bidirectional_lstm_1"
)))
model_v3.add(Dropout(DROPOUT_RATE_LSTM, name="dropout_lstm1"))

# 3. Second Bidirectional LSTM Layer
model_v3.add(Bidirectional(LSTM(
    units=LSTM_UNITS_L2,
    return_sequences=True,
    dropout=LSTM_INTERNAL_DROPOUT,
    recurrent_dropout=LSTM_INTERNAL_DROPOUT,
    name="bidirectional_lstm_2"
)))
model_v3.add(Dropout(DROPOUT_RATE_LSTM, name="dropout_lstm2"))

model_v3.add(TimeDistributed(Dense(
    units=STRUCT_VOCAB_SIZE,
    activation='softmax',
    name="output_dense_layer"
)))

model_v3.compile(
    optimizer=tf.keras.optimizers.Adam(learning_rate=0.001),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)
print("\n--- Building model_v3 explicitly with input_shape ---")
try:
    model_v3.build(input_shape=(None, EXPECTED_MAX_LEN))
    print("Model v3 built successfully.")
    print("\n--- Model v3 Summary ---")
    model_v3.summary()
except Exception as e:
    print(f"🔴 Error during explicit model_v3.build(): {e}")
    print("   Ensure EXPECTED_MAX_LEN is a valid integer.")
    print("\n--- Model v3 Summary (may be unbuilt) ---")
    model_v3.summary()


print("\nModel v3 (Deeper BiLSTM) defined and compiled successfully.")

