import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay

print(f"--- Evaluating Model v3 for Dataset 2 ---") # Name reflects model and dataset

# --- Ensure Test Data and Model are Available ---

# Load the best model_v3 saved by ModelCheckpoint after training on Dataset 1
MODEL_TO_LOAD_PATH_V3_DS2 = '/content/drive/My Drive/RNA_Project_Models/best_model_v3_dataset2.keras' # Correct path for v3, dataset 1
print(f"Loading model from: {MODEL_TO_LOAD_PATH_V3_DS2}")
model_to_evaluate_ds2_v3 = None # Initialize
try:
    # Load the model_v3 for dataset 1
    loaded_model_ds2_v3 = tf.keras.models.load_model(MODEL_TO_LOAD_PATH_V3_DS2)
    print(f"Model '{os.path.basename(MODEL_TO_LOAD_PATH_V3_DS2)}' loaded successfully.") # Use basename for cleaner print
    model_to_evaluate_ds2_v3 = loaded_model_ds2_v3 # Use the loaded model
except Exception as e:
    print(f"🔴 Error loading model '{MODEL_TO_LOAD_PATH_V3_DS2}': {e}.")
    print("   Please ensure the model was saved correctly after training Dataset 2 (v3).")
    # Fallback to a globally available 'model_v3' if it exists (less ideal for formal eval if not from file)
    if 'model_v3' in globals(): # Check for the model instance from the training cell
        print("Using 'model_v3' variable from the current session's training (ensure it's the one for Dataset 2).")
        model_to_evaluate_ds2_v3 = model_v3 # Assumes 'model_v3' is the correct trained instance
    else:
        print("🔴 ERROR: No model available for evaluation for Dataset 2 (v3).")
        raise NameError("Model for Dataset 2 (v3) not found.") # Stop execution

# Ensure test data for Dataset 1 is loaded and available
if 'X_test_2_split' not in globals() or 'y_test_2_split' not in globals():
    print("🔴 ERROR: Test data (X_test_2_split, y_test_2_split) not found. Please run the data splitting cell for Dataset 1 first.")
    raise NameError("Test data for Dataset 2 not found.")
else:
    current_X_test_ds2 = X_test_2_split
    current_y_test_ds2 = y_test_2_split

    print(f"Evaluating with test data shape: X={current_X_test_ds2.shape}, y={current_y_test_ds2.shape}")

    # --- 1. Overall Loss and Accuracy (includes padding) ---
    loss_ds2_v3, accuracy_ds2_v3 = model_to_evaluate_ds2_v3.evaluate(current_X_test_ds2, current_y_test_ds2, verbose=0)
    print(f"\nTest Loss (Dataset 2, v3): {loss_ds2_v3:.4f}")
    print(f"Test Accuracy (Dataset 2, v3 - overall, considers padding): {accuracy_ds2_v3:.4f}")

    # --- 2. Predictions and More Detailed Metrics (Ignoring Padding) ---
    y_pred_probabilities_ds2_v3 = model_to_evaluate_ds2_v3.predict(current_X_test_ds2)
    y_pred_classes_ds2_v3 = np.argmax(y_pred_probabilities_ds2_v3, axis=-1)

    # Flatten true and predicted labels, and remove padding
    if 'CHAR_TO_INT_STRUCT' not in globals() or '<PAD>' not in CHAR_TO_INT_STRUCT or 'INT_TO_CHAR_STRUCT' not in globals():
        print("🔴 ERROR: CHAR_TO_INT_STRUCT or INT_TO_CHAR_STRUCT or their '<PAD>' key is not defined (from Cell 1). Cannot calculate metrics without padding.")
    else:
        PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']
        y_true_flat_no_pad_ds2_v3 = [] # Using v3 suffix for clarity
        y_pred_flat_no_pad_ds2_v3 = [] # Using v3 suffix

        for i in range(len(current_y_test_ds1)):
            true_struct_sample_ds2 = current_y_test_ds2[i]
            pred_struct_sample_ds2_v3 = y_pred_classes_ds2_v3[i]

            actual_len = len(true_struct_sample_ds2)
            try:
                first_pad_idx = np.where(true_struct_sample_ds2 == PAD_TOKEN_STRUCT_INT)[0][0]
                actual_len = first_pad_idx
            except IndexError:
                pass

            y_true_flat_no_pad_ds2_v3.extend(true_struct_sample_ds2[:actual_len])
            y_pred_flat_no_pad_ds2_v3.extend(pred_struct_sample_ds2_v3[:actual_len])

        y_true_flat_no_pad_ds2_v3 = np.array(y_true_flat_no_pad_ds2_v3)
        y_pred_flat_no_pad_ds2_v3 = np.array(y_pred_flat_no_pad_ds2_v3)

        if len(y_true_flat_no_pad_ds2_v3) > 0:
            print("\nClassification Report for Dataset 2 (v3, excluding padding):")

            unique_labels_in_data_ds2_v3 = np.unique(np.concatenate((y_true_flat_no_pad_ds2_v3, y_pred_flat_no_pad_ds2_v3)))
            struct_class_labels_ds2_v3 = [INT_TO_CHAR_STRUCT.get(i, str(i)) for i in unique_labels_in_data_ds2_v3 if i != PAD_TOKEN_STRUCT_INT]
            report_labels_int_ds2_v3 = [i for i in unique_labels_in_data_ds2_v3 if i != PAD_TOKEN_STRUCT_INT]

            print(classification_report(
                y_true_flat_no_pad_ds2_v3,
                y_pred_flat_no_pad_ds2_v3,
                labels=report_labels_int_ds2_v3,
                target_names=struct_class_labels_ds2_v3,
                zero_division=0
            ))

            print("\nConfusion Matrix for Dataset 2 (v3, excluding padding):")
            cm_ds2_v3 = confusion_matrix(
                y_true_flat_no_pad_ds2_v3,
                y_pred_flat_no_pad_ds2_v3,
                labels=report_labels_int_ds2_v3
            )
            disp_ds2_v3 = ConfusionMatrixDisplay(confusion_matrix=cm_ds2_v3, display_labels=struct_class_labels_ds2_v3)
            disp_ds2_v3.plot(cmap=plt.cm.Blues)
            plt.title("Confusion Matrix - Dataset 2 (v3)") # Updated title
            plt.show()
        else:
            print("🔴 No non-padded data to calculate detailed metrics for Dataset 2 (v3).")

