import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay

print(f"--- Evaluating Model v3 for Dataset 4 ---")
MODEL_TO_LOAD_PATH_V3_DS4 = '/content/drive/My Drive/RNA_Project_Models/best_model_v3_dataset4.keras'
print(f"Loading model from: {MODEL_TO_LOAD_PATH_V3_DS4}")
model_to_evaluate_ds4_v3 = None
try:
    loaded_model_ds4_v3 = tf.keras.models.load_model(MODEL_TO_LOAD_PATH_V3_DS4)
    print(f"Model '{os.path.basename(MODEL_TO_LOAD_PATH_V3_DS4)}' loaded successfully.")
    model_to_evaluate_ds4_v3 = loaded_model_ds4_v3
except Exception as e:
    print(f"🔴 Error loading model '{MODEL_TO_LOAD_PATH_V3_DS4}': {e}.")
    print("   Please ensure the model was saved correctly after training Dataset 4 (v3).")
    if 'model_v3' in globals():
        print("Using 'model_v3' variable from the current session's training (ensure it's the one for Dataset 4).")
        model_to_evaluate_ds3_v3 = model_v3
    else:
        print("🔴 ERROR: No model available for evaluation for Dataset 4 (v3).")
        raise NameError("Model for Dataset 4 (v3) not found.")

if 'X_test_4_split' not in globals() or 'y_test_4_split' not in globals():
    print("🔴 ERROR: Test data (X_test_4_split, y_test_4_split) not found. Please run the data splitting cell for Dataset 4 first.")
    raise NameError("Test data for Dataset 4 not found.")
else:
    current_X_test_ds4 = X_test_4_split
    current_y_test_ds4 = y_test_4_split

    print(f"Evaluating with test data shape: X={current_X_test_ds4.shape}, y={current_y_test_ds4.shape}")

    loss_ds4_v3, accuracy_ds4_v3 = model_to_evaluate_ds4_v3.evaluate(current_X_test_ds4, current_y_test_ds4, verbose=0)
    print(f"\nTest Loss (Dataset 4, v3): {loss_ds4_v3:.4f}")
    print(f"Test Accuracy (Dataset 4, v3 - overall, considers padding): {accuracy_ds4_v3:.4f}")

    y_pred_probabilities_ds4_v3 = model_to_evaluate_ds4_v3.predict(current_X_test_ds4)
    y_pred_classes_ds4_v3 = np.argmax(y_pred_probabilities_ds4_v3, axis=-1)

    if 'CHAR_TO_INT_STRUCT' not in globals() or '<PAD>' not in CHAR_TO_INT_STRUCT or 'INT_TO_CHAR_STRUCT' not in globals():
        print("🔴 ERROR: CHAR_TO_INT_STRUCT or INT_TO_CHAR_STRUCT or their '<PAD>' key is not defined (from Cell 1). Cannot calculate metrics without padding.")
    else:
        PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']
        y_true_flat_no_pad_ds4_v3 = []
        y_pred_flat_no_pad_ds4_v3 = []

        for i in range(len(current_y_test_ds3)):
            true_struct_sample_ds4 = current_y_test_ds3[i]
            pred_struct_sample_ds4_v3 = y_pred_classes_ds4_v3[i]

            actual_len = len(true_struct_sample_ds3)
            try:
                first_pad_idx = np.where(true_struct_sample_ds4 == PAD_TOKEN_STRUCT_INT)[0][0]
                actual_len = first_pad_idx
            except IndexError:
                pass

            y_true_flat_no_pad_ds4_v3.extend(true_struct_sample_ds4[:actual_len])
            y_pred_flat_no_pad_ds4_v3.extend(pred_struct_sample_ds4_v3[:actual_len])

        y_true_flat_no_pad_ds4_v3 = np.array(y_true_flat_no_pad_ds4_v3)
        y_pred_flat_no_pad_ds4_v3 = np.array(y_pred_flat_no_pad_ds4_v3)

        if len(y_true_flat_no_pad_ds4_v3) > 0:
            print("\nClassification Report for Dataset 4 (v3, excluding padding):")

            unique_labels_in_data_ds4_v3 = np.unique(np.concatenate((y_true_flat_no_pad_ds4_v3, y_pred_flat_no_pad_ds4_v3)))
            struct_class_labels_ds4_v3 = [INT_TO_CHAR_STRUCT.get(i, str(i)) for i in unique_labels_in_data_ds4_v3 if i != PAD_TOKEN_STRUCT_INT]
            report_labels_int_ds4_v3 = [i for i in unique_labels_in_data_ds4_v3 if i != PAD_TOKEN_STRUCT_INT]

            print(classification_report(
                y_true_flat_no_pad_ds4_v3,
                y_pred_flat_no_pad_ds4_v3,
                labels=report_labels_int_ds4_v3,
                target_names=struct_class_labels_ds4_v3,
                zero_division=0
            ))

            print("\nConfusion Matrix for Dataset 4 (v3, excluding padding):")
            cm_ds4_v3 = confusion_matrix(
                y_true_flat_no_pad_ds4_v3,
                y_pred_flat_no_pad_ds4_v3,
                labels=report_labels_int_ds4_v3
            )
            disp_ds4_v3 = ConfusionMatrixDisplay(confusion_matrix=cm_ds4_v3, display_labels=struct_class_labels_ds4_v3)
            disp_ds4_v3.plot(cmap=plt.cm.Blues)
            plt.title("Confusion Matrix - Dataset 4 (v3)")
            plt.show()
        else:
            print("🔴 No non-padded data to calculate detailed metrics for Dataset 4 (v3).")

import numpy as np
import matplotlib.pyplot as plt
from collections import Counter
from sklearn.utils import class_weight

CURRENT_DATASET_ID_FOR_WEIGHTS = 1
print(f"--- Analyzing Class Distribution & Calculating Weights for y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split ---")

y_train_current_for_weights = globals().get(f'y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split')

if y_train_current_for_weights is None or \
   'CHAR_TO_INT_STRUCT' not in globals() or \
   'INT_TO_CHAR_STRUCT' not in globals():
    print(f"🔴 ERROR: y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split or CHAR_TO_INT_STRUCT/INT_TO_CHAR_STRUCT not found.")
    print("   Please load, process, and split the data first, and ensure Cell 1 ran.")
else:
    PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']

    all_true_labels_no_pad_train = []
    for i in range(len(y_train_current_for_weights)):
        true_struct_sample = y_train_current_for_weights[i]
        actual_len = len(true_struct_sample)
        try:
            first_pad_idx = np.where(true_struct_sample == PAD_TOKEN_STRUCT_INT)[0][0]
            actual_len = first_pad_idx
        except IndexError:
            pass
        all_true_labels_no_pad_train.extend(true_struct_sample[:actual_len])

    if not all_true_labels_no_pad_train:
        print("🔴 No non-padded labels found in the training data to analyze.")
    else:
        label_counts_train = Counter(all_true_labels_no_pad_train)
        print("\nRaw integer label counts in training data (excluding padding):")
        for label_int, count in label_counts_train.items():
            char_label = INT_TO_CHAR_STRUCT.get(label_int, f"Unknown_Int({label_int})")
            print(f"  Token '{char_label}' (int: {label_int}): {count} occurrences")

        total_labels_train = len(all_true_labels_no_pad_train)
        print(f"\nTotal non-padded labels in training set: {total_labels_train}")
        print("Training label percentages (excluding padding):")

        chars_for_plot_train = []
        counts_for_plot_train = []

        for label_int, count in sorted(label_counts_train.items()):
            char_label = INT_TO_CHAR_STRUCT.get(label_int, f"Unknown_Int({label_int})")
            percentage = (count / total_labels_train) * 100
            print(f"  Token '{char_label}': {percentage:.2f}%")
            if label_int != PAD_TOKEN_STRUCT_INT:
                 chars_for_plot_train.append(char_label)
                 counts_for_plot_train.append(count)

        if chars_for_plot_train:
            plt.figure(figsize=(8, 5))
            plt.bar(chars_for_plot_train, counts_for_plot_train)
            plt.title(f'Dataset {CURRENT_DATASET_ID_FOR_WEIGHTS} Training: Class Distribution (No Padding)')
            plt.xlabel('Structure Element')
            plt.ylabel('Frequency Count')
            plt.show()

        unique_classes_train = np.unique(all_true_labels_no_pad_train)
        unique_classes_train_no_pad = [cls for cls in unique_classes_train if cls != PAD_TOKEN_STRUCT_INT]

        if not unique_classes_train_no_pad:
            print("🔴 ERROR: No non-padding classes found in training data to calculate weights for.")
        else:
            class_weights_calculated_array = class_weight.compute_class_weight(
                class_weight='balanced',
                classes=np.array(unique_classes_train_no_pad),
                y=np.array(all_true_labels_no_pad_train)
            )

            class_weight_dict_current = {unique_classes_train_no_pad[i]: class_weights_calculated_array[i] for i in range(len(unique_classes_train_no_pad))}

            print(f"\nCalculated class weights for Dataset {CURRENT_DATASET_ID_FOR_WEIGHTS} (for non-padding classes):")
            for class_int, weight_val in class_weight_dict_current.items():
                print(f"  Class {INT_TO_CHAR_STRUCT.get(class_int)} (int: {class_int}): {weight_val:.4f}")

            sample_weights_current = np.ones_like(y_train_current_for_weights, dtype=float)

            for class_int, weight in class_weight_dict_current.items():
                sample_weights_current[y_train_current_for_weights == class_int] = weight

            sample_weights_current[y_train_current_for_weights == PAD_TOKEN_STRUCT_INT] = 0.0

            globals()[f'sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}'] = sample_weights_current
            print(f"\n`sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}` array created with shape {sample_weights_current.shape}.")
            print(f"Example weights (first sample, first 10 timesteps): {sample_weights_current[0, :10]}")
            print(f"Unique weight values in sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}: {np.unique(sample_weights_current)}")

"""# **Model V2+Class Balancing**

"""

import tensorflow as tf
from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Embedding, Bidirectional, LSTM, Dense, TimeDistributed, Dropout

print("--- Defining the RNA Secondary Structure Prediction Model (v2 architecture) ---")

EMBEDDING_DIM = 128
LSTM_UNITS = 256
DROPOUT_RATE = 0.3
LSTM_DROPOUT_RATE = 0.2

if 'SEQ_VOCAB_SIZE' not in globals() : SEQ_VOCAB_SIZE = 5
if 'STRUCT_VOCAB_SIZE' not in globals() : STRUCT_VOCAB_SIZE = 4
if 'EXPECTED_MAX_LEN' not in globals() : EXPECTED_MAX_LEN = 150


model_v2_balanced = Sequential(name="RNA_Structure_Predictor_v2_Balanced")

model_v2_balanced.add(Embedding(
    input_dim=SEQ_VOCAB_SIZE, output_dim=EMBEDDING_DIM, input_length=EXPECTED_MAX_LEN,
    name="embedding_layer"
))
model_v2_balanced.add(Dropout(DROPOUT_RATE, name="dropout_embedding"))
model_v2_balanced.add(Bidirectional(LSTM(
    units=LSTM_UNITS, return_sequences=True, dropout=LSTM_DROPOUT_RATE,
    recurrent_dropout=LSTM_DROPOUT_RATE, name="bidirectional_lstm_1"
)))
model_v2_balanced.add(Dropout(DROPOUT_RATE, name="dropout_lstm1"))
model_v2_balanced.add(TimeDistributed(Dense(
    units=STRUCT_VOCAB_SIZE, activation='softmax', name="output_dense_layer"
)))

model_v2_balanced.compile(
    optimizer=tf.keras.optimizers.Adam(learning_rate=0.001),
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

print("\n--- Building model_v2_balanced explicitly with input_shape ---")
try:
    if not isinstance(EXPECTED_MAX_LEN, int):
        print(f"🔴 WARNING: EXPECTED_MAX_LEN ({EXPECTED_MAX_LEN}) is not an integer. Attempting conversion or using default 150.")
        try:
            EXPECTED_MAX_LEN = int(EXPECTED_MAX_LEN)
        except:
            EXPECTED_MAX_LEN = 150

    model_v2_balanced.build(input_shape=(None, EXPECTED_MAX_LEN))
    print("Model v2_balanced built successfully.")
    print("\n--- Model v2_balanced Summary (After Explicit Build) ---")
    model_v2_balanced.summary()
except Exception as e:
    print(f"🔴 Error during explicit model_v2_balanced.build(): {e}")
    print("   Ensure EXPECTED_MAX_LEN is a valid integer.")
    print("\n--- Model v2_balanced Summary (may be unbuilt if build failed) ---")
    model_v2_balanced.summary()
print("\nModel v2 (for balanced training) defined and compiled successfully.")

from tensorflow.keras.callbacks import ModelCheckpoint, EarlyStopping
import matplotlib.pyplot as plt

CURRENT_DATASET_ID_TO_TRAIN = 1
print(f"--- Preparing for Balanced Model Training: model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")

X_train_current = globals().get(f'X_train_{CURRENT_DATASET_ID_TO_TRAIN}_split')
y_train_current = globals().get(f'y_train_{CURRENT_DATASET_ID_TO_TRAIN}_split')
X_val_current = globals().get(f'X_val_{CURRENT_DATASET_ID_TO_TRAIN}_split')
y_val_current = globals().get(f'y_val_{CURRENT_DATASET_ID_TO_TRAIN}_split')
current_sample_weights = globals().get(f'sample_weights_{CURRENT_DATASET_ID_TO_TRAIN}')


if X_train_current is None or y_train_current is None or \
   X_val_current is None or y_val_current is None or \
   current_sample_weights is None:
    print(f"🔴 ERROR: Training/validation data or sample_weights for Dataset {CURRENT_DATASET_ID_TO_TRAIN} not found.")
    print("   Please run data loading, splitting, and Cell A (weight calculation) for this dataset first.")
elif 'model_v2_balanced' not in globals():
    print("🔴 ERROR: 'model_v2_balanced' not found. Please define and compile it by running Cell B first.")
else:
    EPOCHS_V2_BAL = 50
    BATCH_SIZE_V2_BAL = 64

    checkpoint_filepath_v2_bal_ds1 = f'/content/drive/My Drive/RNA_Project_Models/best_model_v2_balanced_dataset{CURRENT_DATASET_ID_TO_TRAIN}.keras'
    model_checkpoint_cb_v2_bal = ModelCheckpoint(
        filepath=checkpoint_filepath_v2_bal_ds1, save_weights_only=False,
        monitor='val_loss', mode='min', save_best_only=True, verbose=1
    )
    early_stopping_cb_v2_bal = EarlyStopping(
        monitor='val_loss', patience=10, verbose=1, mode='min', restore_best_weights=True
    )

    print(f"\n--- Starting BALANCED Model Training: model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")
    print(f"Using sample_weights_{CURRENT_DATASET_ID_TO_TRAIN} with shape {current_sample_weights.shape}")

    history_v2_bal_ds1 = model_v2_balanced.fit(
        X_train_current,
        y_train_current,
        sample_weight=current_sample_weights,
        epochs=EPOCHS_V2_BAL,
        batch_size=BATCH_SIZE_V2_BAL,
        validation_data=(X_val_current, y_val_current),
        callbacks=[model_checkpoint_cb_v2_bal, early_stopping_cb_v2_bal],
        verbose=1
    )

    print(f"\n--- Model Training Finished for model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")

    if history_v2_bal_ds1:
        plt.figure(figsize=(12, 5))
        plt.subplot(1, 2, 1)
        plt.plot(history_v2_bal_ds1.history['loss'], label='Training Loss')
        plt.plot(history_v2_bal_ds1.history['val_loss'], label='Validation Loss')
        plt.title(f'model_v2_balanced - Dataset {CURRENT_DATASET_ID_TO_TRAIN}: Loss')
        plt.xlabel('Epoch'); plt.ylabel('Loss'); plt.legend(); plt.grid(True)
        plt.subplot(1, 2, 2)
        plt.plot(history_v2_bal_ds1.history['accuracy'], label='Training Accuracy')
        plt.plot(history_v2_bal_ds1.history['val_accuracy'], label='Validation Accuracy')
        plt.title(f'model_v2_balanced - Dataset {CURRENT_DATASET_ID_TO_TRAIN}: Accuracy')
        plt.xlabel('Epoch'); plt.ylabel('Accuracy'); plt.legend(); plt.grid(True)
        plt.tight_layout(); plt.show()

import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay
import os

CURRENT_DATASET_ID_TO_EVALUATE = 1
MODEL_VERSION_TAG = "v2_balanced"

print(f"--- Evaluating Model '{MODEL_VERSION_TAG}' for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ---")

if 'CHAR_TO_INT_STRUCT' not in globals() or \
   '<PAD>' not in CHAR_TO_INT_STRUCT or \
   'INT_TO_CHAR_STRUCT' not in globals():
    print("🔴 ERROR: CHAR_TO_INT_STRUCT or INT_TO_CHAR_STRUCT or their '<PAD>' key is not defined (from Cell 1).")
    print("   Cannot calculate metrics without padding information. Please run Cell 1.")
    raise NameError("Missing structural character mapping dictionaries from Cell 1.")

MODEL_TO_LOAD_PATH = f'/content/drive/My Drive/RNA_Project_Models/best_model_{MODEL_VERSION_TAG}_dataset{CURRENT_DATASET_ID_TO_EVALUATE}.keras'

print(f"Attempting to load model from: {MODEL_TO_LOAD_PATH}")

model_to_evaluate = None
try:
    if not os.path.exists(MODEL_TO_LOAD_PATH):
        raise FileNotFoundError(f"Model file not found at {MODEL_TO_LOAD_PATH}")
    model_to_evaluate = tf.keras.models.load_model(MODEL_TO_LOAD_PATH)
    print(f"Model '{os.path.basename(MODEL_TO_LOAD_PATH)}' loaded successfully.")
except Exception as e:
    print(f"🔴 Error loading model '{MODEL_TO_LOAD_PATH}': {e}.")
    model_in_memory_name = f"model_{MODEL_VERSION_TAG}"
    if model_in_memory_name in globals():
        print(f"Warning: Using '{model_in_memory_name}' variable from the current session's training.")
        print("         This might not be the 'best' model if EarlyStopping didn't restore best weights,")
        print("         or if this is not immediately after training the correct dataset.")
        model_to_evaluate = globals()[model_in_memory_name]
    else:
        print(f"🔴 ERROR: No model '{model_in_memory_name}' found in memory, and loading from file failed.")
        raise NameError(f"No model available for evaluation for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}).")

X_test_current = globals().get(f'X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')
y_test_current = globals().get(f'y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')

if X_test_current is None or y_test_current is None:
    print(f"🔴 ERROR: Test data (X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split, y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split) not found.")
    print(f"   Please run the data loading, processing, and splitting cells for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} first.")
    raise NameError(f"Test data for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} not found.")
else:
    print(f"\nEvaluating with test data shape: X={X_test_current.shape}, y={y_test_current.shape}")

    loss_overall, accuracy_overall = model_to_evaluate.evaluate(X_test_current, y_test_current, verbose=0)
    print(f"\nTest Loss (Dataset {CURRENT_DATASET_ID_TO_EVALUATE}, {MODEL_VERSION_TAG}): {loss_overall:.4f}")
    print(f"Test Accuracy (Dataset {CURRENT_DATASET_ID_TO_EVALUATE}, {MODEL_VERSION_TAG} - overall, considers padding): {accuracy_overall:.4f}")

    y_pred_probabilities_current = model_to_evaluate.predict(X_test_current, batch_size=BATCH_SIZE_V2_BAL if 'BATCH_SIZE_V2_BAL' in globals() else 64)
    y_pred_classes_current = np.argmax(y_pred_probabilities_current, axis=-1)

    PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']
    y_true_flat_no_pad_current = []
    y_pred_flat_no_pad_current = []

    for i in range(len(y_test_current)):
        true_struct_sample = y_test_current[i]
        pred_struct_sample = y_pred_classes_current[i]
        actual_len = len(true_struct_sample)
        try:
            first_pad_idx = np.where(true_struct_sample == PAD_TOKEN_STRUCT_INT)[0][0]
            actual_len = first_pad_idx
        except IndexError:
            pass
        y_true_flat_no_pad_current.extend(true_struct_sample[:actual_len])
        y_pred_flat_no_pad_current.extend(pred_struct_sample[:actual_len])

    y_true_flat_no_pad_current = np.array(y_true_flat_no_pad_current)
    y_pred_flat_no_pad_current = np.array(y_pred_flat_no_pad_current)

    if len(y_true_flat_no_pad_current) > 0:
        print(f"\nClassification Report for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}, excluding padding):")
        unique_labels_in_data_current = np.unique(np.concatenate((y_true_flat_no_pad_current, y_pred_flat_no_pad_current)))
        struct_class_labels_current = [INT_TO_CHAR_STRUCT.get(i, str(i)) for i in unique_labels_in_data_current if i != PAD_TOKEN_STRUCT_INT]
        report_labels_int_current = [i for i in unique_labels_in_data_current if i != PAD_TOKEN_STRUCT_INT]

        defined_struct_chars_no_pad = [INT_TO_CHAR_STRUCT[i] for i in CHAR_TO_INT_STRUCT.values() if i != PAD_TOKEN_STRUCT_INT]
        defined_struct_ints_no_pad = [CHAR_TO_INT_STRUCT[c] for c in defined_struct_chars_no_pad]


        print(classification_report(
            y_true_flat_no_pad_current,
            y_pred_flat_no_pad_current,
            labels=defined_struct_ints_no_pad,
            target_names=defined_struct_chars_no_pad,
            zero_division=0
        ))

        print(f"\nConfusion Matrix for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}, excluding padding):")
        cm_current = confusion_matrix(
            y_true_flat_no_pad_current,
            y_pred_flat_no_pad_current,
            labels=defined_struct_ints_no_pad
        )
        disp_current = ConfusionMatrixDisplay(confusion_matrix=cm_current, display_labels=defined_struct_chars_no_pad)
        disp_current.plot(cmap=plt.cm.Blues)
        plt.title(f"Confusion Matrix - Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG})")
        plt.show()
    else:
        print(f"🔴 No non-padded data to calculate detailed metrics for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}).")

# Cell A: Check Class Distribution & Calculate Sample Weights (e.g., for Dataset 1)

import numpy as np
import matplotlib.pyplot as plt
from collections import Counter
from sklearn.utils import class_weight

CURRENT_DATASET_ID_FOR_WEIGHTS = 2
print(f"--- Analyzing Class Distribution & Calculating Weights for y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split ---")

y_train_current_for_weights = globals().get(f'y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split')

if y_train_current_for_weights is None or \
   'CHAR_TO_INT_STRUCT' not in globals() or \
   'INT_TO_CHAR_STRUCT' not in globals():
    print(f"🔴 ERROR: y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split or CHAR_TO_INT_STRUCT/INT_TO_CHAR_STRUCT not found.")
    print("   Please load, process, and split the data first, and ensure Cell 1 ran.")
else:
    PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']

    all_true_labels_no_pad_train = []
    for i in range(len(y_train_current_for_weights)):
        true_struct_sample = y_train_current_for_weights[i]
        actual_len = len(true_struct_sample)
        try:
            first_pad_idx = np.where(true_struct_sample == PAD_TOKEN_STRUCT_INT)[0][0]
            actual_len = first_pad_idx
        except IndexError:
            pass
        all_true_labels_no_pad_train.extend(true_struct_sample[:actual_len])

    if not all_true_labels_no_pad_train:
        print("🔴 No non-padded labels found in the training data to analyze.")
    else:

        label_counts_train = Counter(all_true_labels_no_pad_train)
        print("\nRaw integer label counts in training data (excluding padding):")
        for label_int, count in label_counts_train.items():
            char_label = INT_TO_CHAR_STRUCT.get(label_int, f"Unknown_Int({label_int})")
            print(f"  Token '{char_label}' (int: {label_int}): {count} occurrences")

        total_labels_train = len(all_true_labels_no_pad_train)
        print(f"\nTotal non-padded labels in training set: {total_labels_train}")
        print("Training label percentages (excluding padding):")

        chars_for_plot_train = []
        counts_for_plot_train = []

        for label_int, count in sorted(label_counts_train.items()):
            char_label = INT_TO_CHAR_STRUCT.get(label_int, f"Unknown_Int({label_int})")
            percentage = (count / total_labels_train) * 100
            print(f"  Token '{char_label}': {percentage:.2f}%")
            if label_int != PAD_TOKEN_STRUCT_INT:
                 chars_for_plot_train.append(char_label)
                 counts_for_plot_train.append(count)

        if chars_for_plot_train:
            plt.figure(figsize=(8, 5))
            plt.bar(chars_for_plot_train, counts_for_plot_train)
            plt.title(f'Dataset {CURRENT_DATASET_ID_FOR_WEIGHTS} Training: Class Distribution (No Padding)')
            plt.xlabel('Structure Element')
            plt.ylabel('Frequency Count')
            plt.show()

        unique_classes_train = np.unique(all_true_labels_no_pad_train)
        unique_classes_train_no_pad = [cls for cls in unique_classes_train if cls != PAD_TOKEN_STRUCT_INT]

        if not unique_classes_train_no_pad:
            print("🔴 ERROR: No non-padding classes found in training data to calculate weights for.")
        else:
            class_weights_calculated_array = class_weight.compute_class_weight(
                class_weight='balanced',
                classes=np.array(unique_classes_train_no_pad),
                y=np.array(all_true_labels_no_pad_train)
            )

            class_weight_dict_current = {unique_classes_train_no_pad[i]: class_weights_calculated_array[i] for i in range(len(unique_classes_train_no_pad))}

            print(f"\nCalculated class weights for Dataset {CURRENT_DATASET_ID_FOR_WEIGHTS} (for non-padding classes):")
            for class_int, weight_val in class_weight_dict_current.items():
                print(f"  Class {INT_TO_CHAR_STRUCT.get(class_int)} (int: {class_int}): {weight_val:.4f}")

            sample_weights_current = np.ones_like(y_train_current_for_weights, dtype=float)

            for class_int, weight in class_weight_dict_current.items():
                sample_weights_current[y_train_current_for_weights == class_int] = weight

            sample_weights_current[y_train_current_for_weights == PAD_TOKEN_STRUCT_INT] = 0.0

            globals()[f'sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}'] = sample_weights_current
            print(f"\n`sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}` array created with shape {sample_weights_current.shape}.")
            print(f"Example weights (first sample, first 10 timesteps): {sample_weights_current[0, :10]}")
            print(f"Unique weight values in sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}: {np.unique(sample_weights_current)}")

from tensorflow.keras.callbacks import ModelCheckpoint, EarlyStopping
import matplotlib.pyplot as plt

CURRENT_DATASET_ID_TO_TRAIN = 2
print(f"--- Preparing for Balanced Model Training: model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")

# Get the correct data splits and sample weights
X_train_current = globals().get(f'X_train_{CURRENT_DATASET_ID_TO_TRAIN}_split')
y_train_current = globals().get(f'y_train_{CURRENT_DATASET_ID_TO_TRAIN}_split')
X_val_current = globals().get(f'X_val_{CURRENT_DATASET_ID_TO_TRAIN}_split')
y_val_current = globals().get(f'y_val_{CURRENT_DATASET_ID_TO_TRAIN}_split')
current_sample_weights = globals().get(f'sample_weights_{CURRENT_DATASET_ID_TO_TRAIN}')


if X_train_current is None or y_train_current is None or \
   X_val_current is None or y_val_current is None or \
   current_sample_weights is None:
    print(f"🔴 ERROR: Training/validation data or sample_weights for Dataset {CURRENT_DATASET_ID_TO_TRAIN} not found.")
    print("   Please run data loading, splitting, and Cell A (weight calculation) for this dataset first.")
elif 'model_v2_balanced' not in globals():
    print("🔴 ERROR: 'model_v2_balanced' not found. Please define and compile it by running Cell B first.")
else:
    # --- Training Hyperparameters ---
    EPOCHS_V2_BAL = 50
    BATCH_SIZE_V2_BAL = 64

    # --- Callbacks ---
    checkpoint_filepath_v2_bal_ds2 = f'/content/drive/My Drive/RNA_Project_Models/best_model_v2_balanced_dataset{CURRENT_DATASET_ID_TO_TRAIN}.keras'
    model_checkpoint_cb_v2_bal = ModelCheckpoint(
        filepath=checkpoint_filepath_v2_bal_ds2, save_weights_only=False,
        monitor='val_loss', mode='min', save_best_only=True, verbose=1
    )
    early_stopping_cb_v2_bal = EarlyStopping(
        monitor='val_loss', patience=10, verbose=1, mode='min', restore_best_weights=True
    )

    print(f"\n--- Starting BALANCED Model Training: model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")
    print(f"Using sample_weights_{CURRENT_DATASET_ID_TO_TRAIN} with shape {current_sample_weights.shape}")

    history_v2_bal_ds2 = model_v2_balanced.fit(
        X_train_current,
        y_train_current,
        sample_weight=current_sample_weights,
        epochs=EPOCHS_V2_BAL,
        batch_size=BATCH_SIZE_V2_BAL,
        validation_data=(X_val_current, y_val_current),
        callbacks=[model_checkpoint_cb_v2_bal, early_stopping_cb_v2_bal],
        verbose=1
    )

    print(f"\n--- Model Training Finished for model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")

    if history_v2_bal_ds2:
        plt.figure(figsize=(12, 5))
        plt.subplot(1, 2, 1)
        plt.plot(history_v2_bal_ds2.history['loss'], label='Training Loss')
        plt.plot(history_v2_bal_ds2.history['val_loss'], label='Validation Loss')
        plt.title(f'model_v2_balanced - Dataset {CURRENT_DATASET_ID_TO_TRAIN}: Loss')
        plt.xlabel('Epoch'); plt.ylabel('Loss'); plt.legend(); plt.grid(True)
        plt.subplot(1, 2, 2)
        plt.plot(history_v2_bal_ds2.history['accuracy'], label='Training Accuracy')
        plt.plot(history_v2_bal_ds2.history['val_accuracy'], label='Validation Accuracy')
        plt.title(f'model_v2_balanced - Dataset {CURRENT_DATASET_ID_TO_TRAIN}: Accuracy')
        plt.xlabel('Epoch'); plt.ylabel('Accuracy'); plt.legend(); plt.grid(True)
        plt.tight_layout(); plt.show()

import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay
import os

CURRENT_DATASET_ID_TO_EVALUATE = 2
MODEL_VERSION_TAG = "v2_balanced" \

print(f"--- Evaluating Model '{MODEL_VERSION_TAG}' for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ---")

if 'CHAR_TO_INT_STRUCT' not in globals() or \
   '<PAD>' not in CHAR_TO_INT_STRUCT or \
   'INT_TO_CHAR_STRUCT' not in globals():
    print("🔴 ERROR: CHAR_TO_INT_STRUCT or INT_TO_CHAR_STRUCT or their '<PAD>' key is not defined (from Cell 1).")
    print("   Cannot calculate metrics without padding information. Please run Cell 1.")
    raise NameError("Missing structural character mapping dictionaries from Cell 1.")

MODEL_TO_LOAD_PATH = f'/content/drive/My Drive/RNA_Project_Models/best_model_{MODEL_VERSION_TAG}_dataset{CURRENT_DATASET_ID_TO_EVALUATE}.keras'

print(f"Attempting to load model from: {MODEL_TO_LOAD_PATH}")

model_to_evaluate = None
try:
    if not os.path.exists(MODEL_TO_LOAD_PATH):
        raise FileNotFoundError(f"Model file not found at {MODEL_TO_LOAD_PATH}")
    model_to_evaluate = tf.keras.models.load_model(MODEL_TO_LOAD_PATH)
    print(f"Model '{os.path.basename(MODEL_TO_LOAD_PATH)}' loaded successfully.")
except Exception as e:
    print(f"🔴 Error loading model '{MODEL_TO_LOAD_PATH}': {e}.")
    model_in_memory_name = f"model_{MODEL_VERSION_TAG}"
    if model_in_memory_name in globals():
        print(f"Warning: Using '{model_in_memory_name}' variable from the current session's training.")
        print("         This might not be the 'best' model if EarlyStopping didn't restore best weights,")
        print("         or if this is not immediately after training the correct dataset.")
        model_to_evaluate = globals()[model_in_memory_name]
    else:
        print(f"🔴 ERROR: No model '{model_in_memory_name}' found in memory, and loading from file failed.")
        raise NameError(f"No model available for evaluation for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}).")


X_test_current = globals().get(f'X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')
y_test_current = globals().get(f'y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')

if X_test_current is None or y_test_current is None:
    print(f"🔴 ERROR: Test data (X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split, y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split) not found.")
    print(f"   Please run the data loading, processing, and splitting cells for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} first.")
    raise NameError(f"Test data for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} not found.")
else:
    print(f"\nEvaluating with test data shape: X={X_test_current.shape}, y={y_test_current.shape}")

    loss_overall, accuracy_overall = model_to_evaluate.evaluate(X_test_current, y_test_current, verbose=0)
    print(f"\nTest Loss (Dataset {CURRENT_DATASET_ID_TO_EVALUATE}, {MODEL_VERSION_TAG}): {loss_overall:.4f}")
    print(f"Test Accuracy (Dataset {CURRENT_DATASET_ID_TO_EVALUATE}, {MODEL_VERSION_TAG} - overall, considers padding): {accuracy_overall:.4f}")

    y_pred_probabilities_current = model_to_evaluate.predict(X_test_current, batch_size=BATCH_SIZE_V2_BAL if 'BATCH_SIZE_V2_BAL' in globals() else 64) # Use a reasonable batch size
    y_pred_classes_current = np.argmax(y_pred_probabilities_current, axis=-1)

    PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']
    y_true_flat_no_pad_current = []
    y_pred_flat_no_pad_current = []

    for i in range(len(y_test_current)):
        true_struct_sample = y_test_current[i]
        pred_struct_sample = y_pred_classes_current[i]
        actual_len = len(true_struct_sample)
        try:
            first_pad_idx = np.where(true_struct_sample == PAD_TOKEN_STRUCT_INT)[0][0]
            actual_len = first_pad_idx
        except IndexError:
            pass
        y_true_flat_no_pad_current.extend(true_struct_sample[:actual_len])
        y_pred_flat_no_pad_current.extend(pred_struct_sample[:actual_len])

    y_true_flat_no_pad_current = np.array(y_true_flat_no_pad_current)
    y_pred_flat_no_pad_current = np.array(y_pred_flat_no_pad_current)

    if len(y_true_flat_no_pad_current) > 0:
        print(f"\nClassification Report for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}, excluding padding):")
        unique_labels_in_data_current = np.unique(np.concatenate((y_true_flat_no_pad_current, y_pred_flat_no_pad_current)))
        struct_class_labels_current = [INT_TO_CHAR_STRUCT.get(i, str(i)) for i in unique_labels_in_data_current if i != PAD_TOKEN_STRUCT_INT]
        report_labels_int_current = [i for i in unique_labels_in_data_current if i != PAD_TOKEN_STRUCT_INT]

        defined_struct_chars_no_pad = [INT_TO_CHAR_STRUCT[i] for i in CHAR_TO_INT_STRUCT.values() if i != PAD_TOKEN_STRUCT_INT]
        defined_struct_ints_no_pad = [CHAR_TO_INT_STRUCT[c] for c in defined_struct_chars_no_pad]


        print(classification_report(
            y_true_flat_no_pad_current,
            y_pred_flat_no_pad_current,
            labels=defined_struct_ints_no_pad,
            target_names=defined_struct_chars_no_pad,
            zero_division=0
        ))

        print(f"\nConfusion Matrix for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}, excluding padding):")
        cm_current = confusion_matrix(
            y_true_flat_no_pad_current,
            y_pred_flat_no_pad_current,
            labels=defined_struct_ints_no_pad
        )
        disp_current = ConfusionMatrixDisplay(confusion_matrix=cm_current, display_labels=defined_struct_chars_no_pad)
        disp_current.plot(cmap=plt.cm.Greens)
        plt.title(f"Confusion Matrix - Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG})")
        plt.show()
    else:
        print(f"🔴 No non-padded data to calculate detailed metrics for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}).")

