MODEL_TO_LOAD_PATH = f'/content/drive/My Drive/RNA_Project_Models/best_model_{MODEL_VERSION_TAG}_dataset{CURRENT_DATASET_ID_TO_EVALUATE}.keras'

print(f"Attempting to load model from: {MODEL_TO_LOAD_PATH}")

model_to_evaluate = None
try:
    if not os.path.exists(MODEL_TO_LOAD_PATH):
        raise FileNotFoundError(f"Model file not found at {MODEL_TO_LOAD_PATH}")
    model_to_evaluate = tf.keras.models.load_model(MODEL_TO_LOAD_PATH)
    print(f"Model '{os.path.basename(MODEL_TO_LOAD_PATH)}' loaded successfully.")
except Exception as e:
    print(f"🔴 Error loading model '{MODEL_TO_LOAD_PATH}': {e}.")
    model_in_memory_name = f"model_{MODEL_VERSION_TAG}"
    if model_in_memory_name in globals():
        print(f"Warning: Using '{model_in_memory_name}' variable from the current session's training.")
        print("         This might not be the 'best' model if EarlyStopping didn't restore best weights,")
        print("         or if this is not immediately after training the correct dataset.")
        model_to_evaluate = globals()[model_in_memory_name]
    else:
        print(f"🔴 ERROR: No model '{model_in_memory_name}' found in memory, and loading from file failed.")
        raise NameError(f"No model available for evaluation for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}).")


# --- Load Test Data for the Current Dataset ---
X_test_current = globals().get(f'X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')
y_test_current = globals().get(f'y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')

if X_test_current is None or y_test_current is None:
    print(f"🔴 ERROR: Test data (X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split, y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split) not found.")
    print(f"   Please run the data loading, processing, and splitting cells for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} first.")
    raise NameError(f"Test data for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} not found.")
else:
    print(f"\nEvaluating with test data shape: X={X_test_current.shape}, y={y_test_current.shape}")

    loss_overall, accuracy_overall = model_to_evaluate.evaluate(X_test_current, y_test_current, verbose=0)
