import numpy as np
import matplotlib.pyplot as plt
from collections import Counter
from sklearn.utils import class_weight
CURRENT_DATASET_ID_FOR_WEIGHTS = 4
print(f"--- Analyzing Class Distribution & Calculating Weights for y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split ---")

y_train_current_for_weights = globals().get(f'y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split')

if y_train_current_for_weights is None or \
   'CHAR_TO_INT_STRUCT' not in globals() or \
   'INT_TO_CHAR_STRUCT' not in globals():
    print(f"🔴 ERROR: y_train_{CURRENT_DATASET_ID_FOR_WEIGHTS}_split or CHAR_TO_INT_STRUCT/INT_TO_CHAR_STRUCT not found.")
    print("   Please load, process, and split the data first, and ensure Cell 1 ran.")
else:
    PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']

    all_true_labels_no_pad_train = []
    for i in range(len(y_train_current_for_weights)):
        true_struct_sample = y_train_current_for_weights[i]
        actual_len = len(true_struct_sample)
        try:
            first_pad_idx = np.where(true_struct_sample == PAD_TOKEN_STRUCT_INT)[0][0]
            actual_len = first_pad_idx
        except IndexError:
            pass
        all_true_labels_no_pad_train.extend(true_struct_sample[:actual_len])

    if not all_true_labels_no_pad_train:
        print("🔴 No non-padded labels found in the training data to analyze.")
    else:
        label_counts_train = Counter(all_true_labels_no_pad_train)
        print("\nRaw integer label counts in training data (excluding padding):")
        for label_int, count in label_counts_train.items():
            char_label = INT_TO_CHAR_STRUCT.get(label_int, f"Unknown_Int({label_int})")
            print(f"  Token '{char_label}' (int: {label_int}): {count} occurrences")

        total_labels_train = len(all_true_labels_no_pad_train)
        print(f"\nTotal non-padded labels in training set: {total_labels_train}")
        print("Training label percentages (excluding padding):")

        chars_for_plot_train = []
        counts_for_plot_train = []

        for label_int, count in sorted(label_counts_train.items()):
            char_label = INT_TO_CHAR_STRUCT.get(label_int, f"Unknown_Int({label_int})")
            percentage = (count / total_labels_train) * 100
            print(f"  Token '{char_label}': {percentage:.2f}%")
            if label_int != PAD_TOKEN_STRUCT_INT:
                 chars_for_plot_train.append(char_label)
                 counts_for_plot_train.append(count)

        if chars_for_plot_train:
            plt.figure(figsize=(8, 5))
            plt.bar(chars_for_plot_train, counts_for_plot_train)
            plt.title(f'Dataset {CURRENT_DATASET_ID_FOR_WEIGHTS} Training: Class Distribution (No Padding)')
            plt.xlabel('Structure Element')
            plt.ylabel('Frequency Count')
            plt.show()

        unique_classes_train = np.unique(all_true_labels_no_pad_train)
        unique_classes_train_no_pad = [cls for cls in unique_classes_train if cls != PAD_TOKEN_STRUCT_INT]

        if not unique_classes_train_no_pad:
            print("🔴 ERROR: No non-padding classes found in training data to calculate weights for.")
        else:
            class_weights_calculated_array = class_weight.compute_class_weight(
                class_weight='balanced',
                classes=np.array(unique_classes_train_no_pad),
                y=np.array(all_true_labels_no_pad_train)
            )

            class_weight_dict_current = {unique_classes_train_no_pad[i]: class_weights_calculated_array[i] for i in range(len(unique_classes_train_no_pad))}

            print(f"\nCalculated class weights for Dataset {CURRENT_DATASET_ID_FOR_WEIGHTS} (for non-padding classes):")
            for class_int, weight_val in class_weight_dict_current.items():
                print(f"  Class {INT_TO_CHAR_STRUCT.get(class_int)} (int: {class_int}): {weight_val:.4f}")

            sample_weights_current = np.ones_like(y_train_current_for_weights, dtype=float)

            for class_int, weight in class_weight_dict_current.items():
                sample_weights_current[y_train_current_for_weights == class_int] = weight
            sample_weights_current[y_train_current_for_weights == PAD_TOKEN_STRUCT_INT] = 0.0

            globals()[f'sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}'] = sample_weights_current
            print(f"\n`sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}` array created with shape {sample_weights_current.shape}.")
            print(f"Example weights (first sample, first 10 timesteps): {sample_weights_current[0, :10]}")
            print(f"Unique weight values in sample_weights_{CURRENT_DATASET_ID_FOR_WEIGHTS}: {np.unique(sample_weights_current)}")

from tensorflow.keras.callbacks import ModelCheckpoint, EarlyStopping
import matplotlib.pyplot as plt

CURRENT_DATASET_ID_TO_TRAIN = 4
print(f"--- Preparing for Balanced Model Training: model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")

X_train_current = globals().get(f'X_train_{CURRENT_DATASET_ID_TO_TRAIN}_split')
y_train_current = globals().get(f'y_train_{CURRENT_DATASET_ID_TO_TRAIN}_split')
X_val_current = globals().get(f'X_val_{CURRENT_DATASET_ID_TO_TRAIN}_split')
y_val_current = globals().get(f'y_val_{CURRENT_DATASET_ID_TO_TRAIN}_split')
current_sample_weights = globals().get(f'sample_weights_{CURRENT_DATASET_ID_TO_TRAIN}')


if X_train_current is None or y_train_current is None or \
   X_val_current is None or y_val_current is None or \
   current_sample_weights is None:
    print(f"🔴 ERROR: Training/validation data or sample_weights for Dataset {CURRENT_DATASET_ID_TO_TRAIN} not found.")
    print("   Please run data loading, splitting, and Cell A (weight calculation) for this dataset first.")
elif 'model_v2_balanced' not in globals():
    print("🔴 ERROR: 'model_v2_balanced' not found. Please define and compile it by running Cell B first.")
else:
    EPOCHS_V2_BAL = 50
    BATCH_SIZE_V2_BAL = 64

    checkpoint_filepath_v2_bal_ds4 = f'/content/drive/My Drive/RNA_Project_Models/best_model_v2_balanced_dataset{CURRENT_DATASET_ID_TO_TRAIN}.keras'
    model_checkpoint_cb_v2_bal = ModelCheckpoint(
        filepath=checkpoint_filepath_v2_bal_ds4, save_weights_only=False,
        monitor='val_loss', mode='min', save_best_only=True, verbose=1
    )
    early_stopping_cb_v2_bal = EarlyStopping(
        monitor='val_loss', patience=10, verbose=1, mode='min', restore_best_weights=True
    )

    print(f"\n--- Starting BALANCED Model Training: model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")
    print(f"Using sample_weights_{CURRENT_DATASET_ID_TO_TRAIN} with shape {current_sample_weights.shape}")

    history_v2_bal_ds2 = model_v2_balanced.fit(
        X_train_current,
        y_train_current,
        sample_weight=current_sample_weights,
        epochs=EPOCHS_V2_BAL,
        batch_size=BATCH_SIZE_V2_BAL,
        validation_data=(X_val_current, y_val_current),
        callbacks=[model_checkpoint_cb_v2_bal, early_stopping_cb_v2_bal],
        verbose=1
    )

    print(f"\n--- Model Training Finished for model_v2_balanced on Dataset {CURRENT_DATASET_ID_TO_TRAIN} ---")

    if history_v2_bal_ds2:
        plt.figure(figsize=(12, 5))
        plt.subplot(1, 2, 1)
        plt.plot(history_v2_bal_ds2.history['loss'], label='Training Loss')
        plt.plot(history_v2_bal_ds2.history['val_loss'], label='Validation Loss')
        plt.title(f'model_v2_balanced - Dataset {CURRENT_DATASET_ID_TO_TRAIN}: Loss')
        plt.xlabel('Epoch'); plt.ylabel('Loss'); plt.legend(); plt.grid(True)
        plt.subplot(1, 2, 2)
        plt.plot(history_v2_bal_ds2.history['accuracy'], label='Training Accuracy')
        plt.plot(history_v2_bal_ds2.history['val_accuracy'], label='Validation Accuracy')
        plt.title(f'model_v2_balanced - Dataset {CURRENT_DATASET_ID_TO_TRAIN}: Accuracy')
        plt.xlabel('Epoch'); plt.ylabel('Accuracy'); plt.legend(); plt.grid(True)
        plt.tight_layout(); plt.show()

