"""# **MODEL V4- CNN+BiLSTM**"""

# Cell 7: Model Definition (v4 - CNN + BiLSTM Hybrid)

import tensorflow as tf
from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Embedding, Conv1D, MaxPooling1D, Bidirectional, LSTM, Dense, TimeDistributed, Dropout, BatchNormalization

print("--- Defining the RNA Secondary Structure Prediction Model (v4 - CNN+BiLSTM) ---")

# --- Model Hyperparameters ---
EMBEDDING_DIM_V4 = 128
CONV_FILTERS_L1_V4 = 128    # Number of filters in the first Conv1D layer
CONV_KERNEL_SIZE_L1_V4 = 5  # Kernel size for the first Conv1D layer
LSTM_UNITS_V4 = 256         # Number of units in the BiLSTM layer
DROPOUT_RATE_EMBED_V4 = 0.2
DROPOUT_RATE_CONV_V4 = 0.25 # Dropout after Conv layers
DROPOUT_RATE_LSTM_V4 = 0.3  # Dropout after BiLSTM layer
LSTM_INTERNAL_DROPOUT_V4 = 0.2 # LSTM's internal dropout

if 'SEQ_VOCAB_SIZE' not in globals() or \
   'STRUCT_VOCAB_SIZE' not in globals() or \
   'EXPECTED_MAX_LEN' not in globals():
    print("🔴 ERROR: SEQ_VOCAB_SIZE, STRUCT_VOCAB_SIZE, or EXPECTED_MAX_LEN not found in globals.")
    SEQ_VOCAB_SIZE = 5; STRUCT_VOCAB_SIZE = 4; EXPECTED_MAX_LEN = 150
    print(f"🔴 WARNING: Using fallback vocab/max_len values.")

model_v4_cnn_bilstm = Sequential(name="RNA_Structure_Predictor_v4_CNN_BiLSTM")

# 1. Embedding Layer
model_v4_cnn_bilstm.add(Embedding(
    input_dim=SEQ_VOCAB_SIZE,
    output_dim=EMBEDDING_DIM_V4,
    input_length=EXPECTED_MAX_LEN,
    name="embedding_layer"
))
model_v4_cnn_bilstm.add(Dropout(DROPOUT_RATE_EMBED_V4, name="dropout_embedding"))

# 2. Convolutional Layer(s)
# First Conv1D Layer
model_v4_cnn_bilstm.add(Conv1D(
    filters=CONV_FILTERS_L1_V4,
    kernel_size=CONV_KERNEL_SIZE_L1_V4,
    padding='same',
    activation='relu',
    name="conv1d_1"
))
model_v4_cnn_bilstm.add(Dropout(DROPOUT_RATE_CONV_V4, name="dropout_conv1"))


# 3. Bidirectional LSTM Layer
# Takes the feature maps from Conv layers as input
model_v4_cnn_bilstm.add(Bidirectional(LSTM(
    units=LSTM_UNITS_V4,
    return_sequences=True,
    dropout=LSTM_INTERNAL_DROPOUT_V4,
    recurrent_dropout=LSTM_INTERNAL_DROPOUT_V4,
    name="bidirectional_lstm_1"
)))
# model_v4_cnn_bilstm.add(BatchNormalization(name="batchnorm_lstm1")) # Optional
model_v4_cnn_bilstm.add(Dropout(DROPOUT_RATE_LSTM_V4, name="dropout_lstm1"))

# 4. TimeDistributed Dense Output Layer
model_v4_cnn_bilstm.add(TimeDistributed(Dense(
    units=STRUCT_VOCAB_SIZE,
    activation='softmax',
    name="output_dense_layer"
)))

# --- Compile the Model ---
model_v4_cnn_bilstm.compile(
    optimizer=tf.keras.optimizers.Adam(learning_rate=0.001), # Adam is a good default
    loss='sparse_categorical_crossentropy',
    metrics=['accuracy']
)

# --- Build Model and Print Summary ---
print("\n--- Building model_v4_cnn_bilstm explicitly with input_shape ---")
try:
    if not isinstance(EXPECTED_MAX_LEN, int): EXPECTED_MAX_LEN = int(EXPECTED_MAX_LEN)
    model_v4_cnn_bilstm.build(input_shape=(None, EXPECTED_MAX_LEN))
    print("Model v4 (CNN+BiLSTM) built successfully.")
    print("\n--- Model v4 (CNN+BiLSTM) Summary ---")
    model_v4_cnn_bilstm.summary()
except Exception as e:
    print(f"🔴 Error during explicit model_v4_cnn_bilstm.build(): {e}")
