# Cell 9: Evaluate model_v4_cnn_bilstm (trained on Dataset 1) on Test Set 1

import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay
import os # For os.path.basename

# --- Configuration for this Evaluation ---
CURRENT_DATASET_ID_TO_EVALUATE = 1
MODEL_VERSION_TAG = "v4_cnn_bilstm" # Reflects the model architecture

print(f"--- Evaluating Model '{MODEL_VERSION_TAG}' for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ---")

# --- Ensure Prerequisite Globals are Available (from Cell 1) ---
if 'CHAR_TO_INT_STRUCT' not in globals() or \
   '<PAD>' not in CHAR_TO_INT_STRUCT or \
   'INT_TO_CHAR_STRUCT' not in globals():
    print("🔴 ERROR: CHAR_TO_INT_STRUCT or INT_TO_CHAR_STRUCT or their '<PAD>' key is not defined (from Cell 1).")
    print("   Cannot calculate metrics without padding information. Please run Cell 1.")
    raise NameError("Missing structural character mapping dictionaries from Cell 1.")

# --- Load the Saved Model ---
model_filename_v4_ds1 = f'best_model_{MODEL_VERSION_TAG}_dataset{CURRENT_DATASET_ID_TO_EVALUATE}.keras'
if 'DRIVE_DATA_PATH' in globals():
    models_folder_path = os.path.join(os.path.dirname(DRIVE_DATA_PATH.rstrip('/')), "RNA_Project_Models")
else:
    models_folder_path = "/content/drive/My Drive/RNA_Project_Models"
    print(f"Warning: DRIVE_DATA_PATH not found, assuming models folder is: {models_folder_path}")

MODEL_TO_LOAD_PATH_V4_DS1 = os.path.join(models_folder_path, model_filename_v4_ds1)

print(f"Attempting to load model from: {MODEL_TO_LOAD_PATH_V4_DS1}")

model_to_evaluate_v4_ds1 = None
try:
    if not os.path.exists(MODEL_TO_LOAD_PATH_V4_DS1):
        raise FileNotFoundError(f"Model file not found at {MODEL_TO_LOAD_PATH_V4_DS1}")
    model_to_evaluate_v4_ds1 = tf.keras.models.load_model(MODEL_TO_LOAD_PATH_V4_DS1)
    print(f"Model '{os.path.basename(MODEL_TO_LOAD_PATH_V4_DS1)}' loaded successfully.")
except Exception as e:
    print(f"🔴 Error loading model '{MODEL_TO_LOAD_PATH_V4_DS1}': {e}.")
    if 'model_v4_cnn_bilstm' in globals():
        print(f"Warning: Using 'model_v4_cnn_bilstm' variable from the current session's training.")
        print("         This might not be the 'best' model if EarlyStopping didn't restore best weights.")
        model_to_evaluate_v4_ds1 = model_v4_cnn_bilstm
    else:
        print(f"🔴 ERROR: No model 'model_v4_cnn_bilstm' found in memory, and loading from file failed.")
        raise NameError(f"No model available for evaluation for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}).")


X_test_1_current = globals().get(f'X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')
y_test_1_current = globals().get(f'y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split')

if X_test_1_current is None or y_test_1_current is None:
    print(f"🔴 ERROR: Test data (X_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split, y_test_{CURRENT_DATASET_ID_TO_EVALUATE}_split) not found.")
    print(f"   Please run the data loading, processing, and splitting cells for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} first.")
    raise NameError(f"Test data for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} not found.")
else:
    print(f"\nEvaluating with test data shape: X={X_test_1_current.shape}, y={y_test_1_current.shape}")

    eval_batch_size = BATCH_SIZE_V4_DS1 if 'BATCH_SIZE_V4_DS1' in globals() else 64

    loss_overall_v4_ds1, accuracy_overall_v4_ds1 = model_to_evaluate_v4_ds1.evaluate(
        X_test_1_current, y_test_1_current, verbose=0, batch_size=eval_batch_size
    )
    print(f"\nTest Loss (Dataset {CURRENT_DATASET_ID_TO_EVALUATE}, {MODEL_VERSION_TAG}): {loss_overall_v4_ds1:.4f}")
    print(f"Test Accuracy (Dataset {CURRENT_DATASET_ID_TO_EVALUATE}, {MODEL_VERSION_TAG} - overall, considers padding): {accuracy_overall_v4_ds1:.4f}")

    y_pred_probabilities_v4_ds1 = model_to_evaluate_v4_ds1.predict(X_test_1_current, batch_size=eval_batch_size)
    y_pred_classes_v4_ds1 = np.argmax(y_pred_probabilities_v4_ds1, axis=-1)

    PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']
    y_true_flat_no_pad_v4_ds1 = []
    y_pred_flat_no_pad_v4_ds1 = []

    for i in range(len(y_test_1_current)):
        true_struct_sample = y_test_1_current[i]
        pred_struct_sample = y_pred_classes_v4_ds1[i]
        actual_len = len(true_struct_sample)
        try:
            first_pad_idx = np.where(true_struct_sample == PAD_TOKEN_STRUCT_INT)[0][0]
            actual_len = first_pad_idx
        except IndexError:
            pass
        y_true_flat_no_pad_v4_ds1.extend(true_struct_sample[:actual_len])
        y_pred_flat_no_pad_v4_ds1.extend(pred_struct_sample[:actual_len])

    y_true_flat_no_pad_v4_ds1 = np.array(y_true_flat_no_pad_v4_ds1)
    y_pred_flat_no_pad_v4_ds1 = np.array(y_pred_flat_no_pad_v4_ds1)

    if len(y_true_flat_no_pad_v4_ds1) > 0:
        print(f"\nClassification Report for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}, excluding padding):")

        defined_struct_chars_no_pad = [char for char_int, char in sorted(INT_TO_CHAR_STRUCT.items()) if char_int != PAD_TOKEN_STRUCT_INT]
        defined_struct_ints_no_pad = [char_int for char_int, char in sorted(INT_TO_CHAR_STRUCT.items()) if char_int != PAD_TOKEN_STRUCT_INT]

        print(classification_report(
            y_true_flat_no_pad_v4_ds1,
            y_pred_flat_no_pad_v4_ds1,
            labels=defined_struct_ints_no_pad,
            target_names=defined_struct_chars_no_pad,
            zero_division=0
        ))

        print(f"\nConfusion Matrix for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}, excluding padding):")
        cm_v4_ds1 = confusion_matrix(
            y_true_flat_no_pad_v4_ds1,
            y_pred_flat_no_pad_v4_ds1,
            labels=defined_struct_ints_no_pad
        )
        disp_v4_ds1 = ConfusionMatrixDisplay(confusion_matrix=cm_v4_ds1, display_labels=defined_struct_chars_no_pad)
        disp_v4_ds1.plot(cmap=plt.cm.Blues)
        plt.title(f"Confusion Matrix - Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG})")
        plt.show()
    else:
        print(f"🔴 No non-padded data to calculate detailed metrics for Dataset {CURRENT_DATASET_ID_TO_EVALUATE} ({MODEL_VERSION_TAG}).")

