import tensorflow as tf
import numpy as np
import matplotlib.pyplot as plt
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay

print(f"--- Evaluating Model v6 for Dataset 1 ---")

MODEL_TO_LOAD_PATH_V6_DS1 = '/content/drive/MyDrive/RNA_Project_Models/best_model_v6_dataset1.keras'
print(f"Loading model from: {MODEL_TO_LOAD_PATH_V6_DS1}")
model_to_evaluate_ds1_v6 = None
try:
    loaded_model_ds1_v6 = tf.keras.models.load_model(MODEL_TO_LOAD_PATH_V6_DS1)
    print(f"Model '{os.path.basename(MODEL_TO_LOAD_PATH_V6_DS1)}' loaded successfully.")
    model_to_evaluate_ds1_v6 = loaded_model_ds1_v6
except Exception as e:
    print(f"🔴 Error loading model '{MODEL_TO_LOAD_PATH_V6_DS1}': {e}.")
    print("   Please ensure the model was saved correctly after training Dataset 1 (v3).")
    if 'model_v3' in globals():
        print("Using 'model_v3' variable from the current session's training (ensure it's the one for Dataset 1).")
        model_to_evaluate_ds1_v6 = model_v6
    else:
        print("🔴 ERROR: No model available for evaluation for Dataset 1 (v6).")
        raise NameError("Model for Dataset 1 (v6) not found.")

if 'X_test_1_split' not in globals() or 'y_test_1_split' not in globals():
    print("🔴 ERROR: Test data (X_test_1_split, y_test_1_split) not found. Please run the data splitting cell for Dataset 1 first.")
    raise NameError("Test data for Dataset 1 not found.")
else:
    current_X_test_ds1 = X_test_1_split
    current_y_test_ds1 = y_test_1_split

    print(f"Evaluating with test data shape: X={current_X_test_ds1.shape}, y={current_y_test_ds1.shape}")

    loss_ds1_v6, accuracy_ds1_v6 = model_to_evaluate_ds1_v6.evaluate(current_X_test_ds1, current_y_test_ds1, verbose=0)
    print(f"\nTest Loss (Dataset 1, v3): {loss_ds1_v6:.4f}")
    print(f"Test Accuracy (Dataset 1, v3 - overall, considers padding): {accuracy_ds1_v6:.4f}")

    y_pred_probabilities_ds1_v6 = model_to_evaluate_ds1_v6.predict(current_X_test_ds1)
    y_pred_classes_ds1_v6 = np.argmax(y_pred_probabilities_ds1_v6, axis=-1)

    if 'CHAR_TO_INT_STRUCT' not in globals() or '<PAD>' not in CHAR_TO_INT_STRUCT or 'INT_TO_CHAR_STRUCT' not in globals():
        print("🔴 ERROR: CHAR_TO_INT_STRUCT or INT_TO_CHAR_STRUCT or their '<PAD>' key is not defined (from Cell 1). Cannot calculate metrics without padding.")
    else:
        PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT['<PAD>']
        y_true_flat_no_pad_ds1_v6 = [] # Using v3 suffix for clarity
        y_pred_flat_no_pad_ds1_v6 = [] # Using v3 suffix

        for i in range(len(current_y_test_ds1)):
            true_struct_sample_ds1 = current_y_test_ds1[i]
            pred_struct_sample_ds1_v6 = y_pred_classes_ds1_v6[i]

            actual_len = len(true_struct_sample_ds1)
            try:
                first_pad_idx = np.where(true_struct_sample_ds1 == PAD_TOKEN_STRUCT_INT)[0][0]
                actual_len = first_pad_idx
            except IndexError:
                pass

            y_true_flat_no_pad_ds1_v6.extend(true_struct_sample_ds1[:actual_len])
            y_pred_flat_no_pad_ds1_v6.extend(pred_struct_sample_ds1_v6[:actual_len])

        y_true_flat_no_pad_ds1_v6 = np.array(y_true_flat_no_pad_ds1_v6)
        y_pred_flat_no_pad_ds1_v6 = np.array(y_pred_flat_no_pad_ds1_v6)

        if len(y_true_flat_no_pad_ds1_v6) > 0:
            print("\nClassification Report for Dataset 1 (v3, excluding padding):")

            unique_labels_in_data_ds1_v6 = np.unique(np.concatenate((y_true_flat_no_pad_ds1_v6, y_pred_flat_no_pad_ds1_v6)))
            struct_class_labels_ds1_v6 = [INT_TO_CHAR_STRUCT.get(i, str(i)) for i in unique_labels_in_data_ds1_v6 if i != PAD_TOKEN_STRUCT_INT]
            report_labels_int_ds1_v6 = [i for i in unique_labels_in_data_ds1_v6 if i != PAD_TOKEN_STRUCT_INT]

            print(classification_report(
                y_true_flat_no_pad_ds1_v6,
                y_pred_flat_no_pad_ds1_v6,
                labels=report_labels_int_ds1_v6,
                target_names=struct_class_labels_ds1_v6,
                zero_division=0
            ))

            print("\nConfusion Matrix for Dataset 1 (v3, excluding padding):")
            cm_ds1_v6 = confusion_matrix(
                y_true_flat_no_pad_ds1_v6,
                y_pred_flat_no_pad_ds1_v6,
                labels=report_labels_int_ds1_v6
            )
            disp_ds1_v6 = ConfusionMatrixDisplay(confusion_matrix=cm_ds1_v6, display_labels=struct_class_labels_ds1_v6)
            disp_ds1_v6.plot(cmap=plt.cm.Blues)
            plt.title("Confusion Matrix - Dataset 1 (v6)") # Updated title
            plt.show()
        else:
            print("🔴 No non-padded data to calculate detailed metrics for Dataset 1 (v3).")

