import tensorflow as tf
from tensorflow.keras.callbacks import ModelCheckpoint, EarlyStopping
import matplotlib.pyplot as plt
import numpy as np
import os # For path joining

# --- Configuration for this Training Run ---
CURRENT_DATASET_ID_FOR_V6_TRAINING = 3 # <<<<<====== SET FOR DATASET 3
FULL_TRAINING_EPOCHS_V6 = 30 # Number of epochs for the full training run (adjust as needed)
BATCH_SIZE_V6 = 64

print(f"--- Preparing to Train Final model_v6 with Best HPs on Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING} ---")

# --- Ensure Best Hyperparameters and Data are Available ---
if 'best_hps_for_v6' not in globals():
    print("🔴 ERROR: 'best_hps_for_v6' not found. Please run the KerasTuner cell (Cell Y) first.")
    raise NameError("'best_hps_for_v6' is not defined.")
else:
    print("Using best hyperparameters found by KerasTuner:")
    # Optionally print the HPs being used for this run
    for param_name in best_hps_for_v6.values:
        print(f"  {param_name}: {best_hps_for_v6.get(param_name)}")


# Get data for the current dataset (Dataset 3)
X_train_v6_current = globals().get(f'X_train_{CURRENT_DATASET_ID_FOR_V6_TRAINING}_split')
y_train_v6_current = globals().get(f'y_train_{CURRENT_DATASET_ID_FOR_V6_TRAINING}_split')
X_val_v6_current = globals().get(f'X_val_{CURRENT_DATASET_ID_FOR_V6_TRAINING}_split')
y_val_v6_current = globals().get(f'y_val_{CURRENT_DATASET_ID_FOR_V6_TRAINING}_split')

# --- Prerequisite Data Checks and Type Conversion ---
if X_train_v6_current is None or y_train_v6_current is None or \
   X_val_v6_current is None or y_val_v6_current is None:
    print(f"🔴 ERROR: Training/validation data for Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING} not found.")
    print(f"   Expected variables: X_train_{CURRENT_DATASET_ID_FOR_V6_TRAINING}_split, etc.")
    print("   Please ensure data loading, processing, and splitting for this dataset have been completed.")
    raise NameError(f"Data for training model_v6 on Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING} is missing.")
else:
    # Ensure correct dtypes
    required_dtype = np.int32
    if X_train_v6_current.dtype != required_dtype: X_train_v6_current = X_train_v6_current.astype(required_dtype)
    if y_train_v6_current.dtype != required_dtype: y_train_v6_current = y_train_v6_current.astype(required_dtype)
    if X_val_v6_current.dtype != required_dtype: X_val_v6_current = X_val_v6_current.astype(required_dtype)
    if y_val_v6_current.dtype != required_dtype: y_val_v6_current = y_val_v6_current.astype(required_dtype)
    print(f"Data for Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING} loaded and types confirmed.")
    print(f"X_train shape: {X_train_v6_current.shape}, y_train shape: {y_train_v6_current.shape}")
    print(f"X_val shape: {X_val_v6_current.shape}, y_val shape: {y_val_v6_current.shape}")


    # --- Build a NEW model instance with the best HPs ---
    # 'build_model_v6_bigru' is your function from Cell X
    print("\nBuilding a new model_v6 instance with best hyperparameters...")
    # It's CRUCIAL to create a new model instance for each dataset training run
    # Give it a unique variable name for this training session if you want to inspect it later,
    # or just reuse 'model_v6_final_instance'. For clarity in logs, let's use a specific name for now.
    model_v6_for_ds3 = build_model_v6_bigru(best_hps_for_v6)
    print("\n--- Summary of Final model_v6 Instance for Dataset 3 ---")
    model_v6_for_ds3.summary()

    # --- Callbacks for this specific training run (Dataset 3) ---
    if 'DRIVE_DATA_PATH' not in globals():
        print("🔴 WARNING: DRIVE_DATA_PATH not defined. Model will be saved locally to Colab.")
        MODELS_SAVE_DIR = "./RNA_Project_Models_V6/"
        if not os.path.exists(MODELS_SAVE_DIR): os.makedirs(MODELS_SAVE_DIR)
    else:
        models_base_folder = os.path.dirname(DRIVE_DATA_PATH.rstrip('/'))
        MODELS_SAVE_DIR = os.path.join(models_base_folder, "RNA_Project_Models")
        if not os.path.exists(MODELS_SAVE_DIR):
            try:
                os.makedirs(MODELS_SAVE_DIR)
                print(f"Created models directory on Drive: {MODELS_SAVE_DIR}")
            except Exception as e_mkdir:
                print(f"🔴 Error creating models directory {MODELS_SAVE_DIR} on Drive: {e_mkdir}")
                MODELS_SAVE_DIR = "./RNA_Project_Models_V6/" # Fallback to local
                if not os.path.exists(MODELS_SAVE_DIR): os.makedirs(MODELS_SAVE_DIR)

    checkpoint_filepath_v6_ds3 = os.path.join(MODELS_SAVE_DIR, f'best_model_v6_dataset{CURRENT_DATASET_ID_FOR_V6_TRAINING}.keras')

    model_checkpoint_v6_ds3 = ModelCheckpoint(
        filepath=checkpoint_filepath_v6_ds3, # Use the specific path for DS3
        save_weights_only=False,
        monitor='val_loss',
        mode='min',
        save_best_only=True,
        verbose=1
    )
    early_stopping_v6_ds3 = EarlyStopping(
        monitor='val_loss',
        patience=10, # Can adjust
        verbose=1,
        mode='min',
        restore_best_weights=True
    )

    print(f"\n--- Starting Full Training for model_v6 on Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING} ---")
    print(f"Max Epochs: {FULL_TRAINING_EPOCHS_V6}, Batch Size: {BATCH_SIZE_V6}")
    print(f"Model will be saved to: {checkpoint_filepath_v6_ds3}") # Confirm correct path

    history_v6_ds3 = model_v6_for_ds3.fit( # Use the model instance for DS3
        X_train_v6_current,
        y_train_v6_current,
        epochs=FULL_TRAINING_EPOCHS_V6,
        batch_size=BATCH_SIZE_V6,
        validation_data=(X_val_v6_current, y_val_v6_current),
        callbacks=[model_checkpoint_v6_ds3, early_stopping_v6_ds3],
        verbose=1
    )

    print(f"\n--- Model Training Finished for model_v6 on Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING} ---")

    # Plotting
    if history_v6_ds3:
        plt.figure(figsize=(12, 5))
        plt.subplot(1, 2, 1)
        plt.plot(history_v6_ds3.history['loss'], label='Training Loss')
        plt.plot(history_v6_ds3.history['val_loss'], label='Validation Loss')
        plt.title(f'model_v6 - Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING}: Loss')
        plt.xlabel('Epoch'); plt.ylabel('Loss'); plt.legend(); plt.grid(True)
        plt.subplot(1, 2, 2)
        plt.plot(history_v6_ds3.history['accuracy'], label='Training Accuracy')
        plt.plot(history_v6_ds3.history['val_accuracy'], label='Validation Accuracy')
        plt.title(f'model_v6 - Dataset {CURRENT_DATASET_ID_FOR_V6_TRAINING}: Accuracy')
        plt.xlabel('Epoch'); plt.ylabel('Accuracy'); plt.legend(); plt.grid(True)
        plt.tight_layout(); plt.show()

