import tensorflow as tf
from tensorflow.keras import layers

# --- Part 1: Define the custom Transformer Encoder layer ---
# This helper class is required by the main function.

class TransformerEncoder(layers.Layer):
    def __init__(self, embed_dim, num_heads, ff_dim, rate=0.1):
        super().__init__()
        self.att = layers.MultiHeadAttention(num_heads=num_heads, key_dim=embed_dim)
        self.ffn = tf.keras.Sequential(
            [layers.Dense(ff_dim, activation="relu"), layers.Dense(embed_dim),]
        )
        self.layernorm1 = layers.LayerNormalization(epsilon=1e-6)
        self.layernorm2 = layers.LayerNormalization(epsilon=1e-6)
        self.dropout1 = layers.Dropout(rate)
        self.dropout2 = layers.Dropout(rate)

    def call(self, inputs, training=None):
        attn_output = self.att(inputs, inputs)
        attn_output = self.dropout1(attn_output, training=training)
        out1 = self.layernorm1(inputs + attn_output)

        ffn_output = self.ffn(out1)
        ffn_output = self.dropout2(ffn_output, training=training)
        return self.layernorm2(out1 + ffn_output)


# --- Part 2: The Main Model-Building Function ---
# This is the function you asked for.

def create_transformer_model_one_hot_input(seq_len=150, vocab_size=4, embed_dim=128, num_heads=8, ff_dim=512):
    """
    Creates a Transformer-based model for RNA secondary structure prediction.

    Args:
        seq_len (int): The length of the input sequences (e.g., 150).
        vocab_size (int): The number of unique characters in the input vocabulary (e.g., 4 for 'A', 'U', 'G', 'C').
        embed_dim (int): The internal dimensionality of the model's vectors.
        num_heads (int): The number of attention heads in the Multi-Head Attention layer.
        ff_dim (int): The dimensionality of the inner layer of the Feed-Forward Network.

    Returns:
        tf.keras.Model: A compiled Keras model ready for training.
    """

    # 1. Define the Input Layer
    # The shape is (sequence_length, number_of_characters_in_vocab)
    inputs = layers.Input(shape=(seq_len, vocab_size))

    # 2. Project the one-hot vectors to the model's internal dimension
    # This replaces the Embedding layer. It's a linear transformation.
    x = layers.Dense(embed_dim)(inputs)

    # 3. Use the custom Transformer Encoder Block
    # You could stack more of these for a deeper model if needed.
    transformer_block = TransformerEncoder(embed_dim=embed_dim, num_heads=num_heads, ff_dim=ff_dim)
    x = transformer_block(x)

    # 4. Prediction Head to create the 2D contact map
    # This part converts the 1D sequence representation into a 2D pairwise representation.
    x_rows = layers.Reshape((seq_len, 1, embed_dim))(x)
    x_cols = layers.Reshape((1, seq_len, embed_dim))(x)

    # Use Lambda layers to wrap the tf.tile function
    x_rows_tiled = layers.Lambda(lambda t: tf.tile(t, [1, 1, seq_len, 1]))(x_rows)
    x_cols_tiled = layers.Lambda(lambda t: tf.tile(t, [1, seq_len, 1, 1]))(x_cols)

    # Concatenate the tiled representations to form pairs
    pairs = layers.Concatenate(axis=-1)([x_rows_tiled, x_cols_tiled])

    # 5. Use a small ConvNet to predict the pairing probability from the pairs
    conv_out = layers.Conv2D(filters=32, kernel_size=1, activation='relu')(pairs)
    # The final prediction layer uses a sigmoid activation to output a probability (0 to 1)
    contact_map_output = layers.Conv2D(filters=1, kernel_size=1, activation='sigmoid')(conv_out)

    # Use a Lambda layer to wrap the tf.squeeze function to remove the last dimension
    contact_map_output = layers.Lambda(lambda t: tf.squeeze(t, axis=-1))(contact_map_output)

    # 6. Create the final model
    model = tf.keras.Model(inputs=inputs, outputs=contact_map_output)

    return model

# --- Example of how to create the model ---
# You can run this to verify it works and see the summary.
# model = create_transformer_model_one_hot_input()
# model.summary()

import tensorflow as tf
from tensorflow.keras import layers
import numpy as np
import matplotlib.pyplot as plt

# --- Part 1: Define ONLY the necessary data functions ---
# We no longer need the model creation functions here.

def one_hot_encode_sequence(sequence, vocab, max_len):
    one_hot_matrix = np.zeros((max_len, len(vocab)), dtype=np.float32)
    for i, char in enumerate(sequence):
        if i < max_len:
            char_index = vocab.get(char)
            if char_index is not None:
                one_hot_matrix[i, char_index] = 1.0
    return one_hot_matrix

def dotbracket_to_contact_map(db_string, max_len):
    contact_map = np.zeros((max_len, max_len), dtype=np.float32)
    stack = []
    for i, char in enumerate(db_string):
        if i < max_len:
            if char == '(':
                stack.append(i)
            elif char == ')':
                if len(stack) > 0:
                    j = stack.pop()
                    contact_map[i, j] = 1.0
                    contact_map[j, i] = 1.0
    return contact_map

