import tensorflow as tf
from tensorflow.keras import layers
import numpy as np
import matplotlib.pyplot as plt

# --- Part 1: Define All Necessary Functions ---

# Helper function for one-hot encoding
def one_hot_encode_sequence(sequence, vocab, max_len):
    one_hot_matrix = np.zeros((max_len, len(vocab)), dtype=np.float32)
    for i, char in enumerate(sequence):
        if i < max_len:
            char_index = vocab.get(char)
            if char_index is not None:
                one_hot_matrix[i, char_index] = 1.0
    return one_hot_matrix

# Helper function for contact map conversion
def dotbracket_to_contact_map(db_string):
    n = len(db_string)
    contact_map = np.zeros((n, n), dtype=np.float32)
    stack = []
    for i, char in enumerate(db_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if len(stack) > 0:
                j = stack.pop()
                contact_map[i, j] = 1.0
                contact_map[j, i] = 1.0
    return contact_map

# The custom TransformerEncoder class
class TransformerEncoder(layers.Layer):
    def __init__(self, embed_dim, num_heads, ff_dim, rate=0.1):
        super().__init__()
        self.att = layers.MultiHeadAttention(num_heads=num_heads, key_dim=embed_dim)
        self.ffn = tf.keras.Sequential(
            [layers.Dense(ff_dim, activation="relu"), layers.Dense(embed_dim),]
        )
        self.layernorm1 = layers.LayerNormalization(epsilon=1e-6)
        self.layernorm2 = layers.LayerNormalization(epsilon=1e-6)
        self.dropout1 = layers.Dropout(rate)
        self.dropout2 = layers.Dropout(rate)

    def call(self, inputs, training=None):
        attn_output = self.att(inputs, inputs)
        attn_output = self.dropout1(attn_output, training=training)
        out1 = self.layernorm1(inputs + attn_output)
        ffn_output = self.ffn(out1)
        ffn_output = self.dropout2(ffn_output, training=training)
        return self.layernorm2(out1 + ffn_output)

# The main model-building function
def create_transformer_model_one_hot_input(seq_len=150, vocab_size=4, embed_dim=128, num_heads=8, ff_dim=512):
    inputs = layers.Input(shape=(seq_len, vocab_size))
    x = layers.Dense(embed_dim)(inputs)
    transformer_block = TransformerEncoder(embed_dim=embed_dim, num_heads=num_heads, ff_dim=ff_dim)
    x = transformer_block(x)
    x_rows = layers.Reshape((seq_len, 1, embed_dim))(x)
    x_cols = layers.Reshape((1, seq_len, embed_dim))(x)
    x_rows_tiled = layers.Lambda(lambda t: tf.tile(t, [1, 1, seq_len, 1]))(x_rows)
    x_cols_tiled = layers.Lambda(lambda t: tf.tile(t, [1, seq_len, 1, 1]))(x_cols)
    pairs = layers.Concatenate(axis=-1)([x_rows_tiled, x_cols_tiled])
    conv_out = layers.Conv2D(filters=32, kernel_size=1, activation='relu')(pairs)
    contact_map_output = layers.Conv2D(filters=1, kernel_size=1, activation='sigmoid')(conv_out)
    contact_map_output = layers.Lambda(lambda t: tf.squeeze(t, axis=-1))(contact_map_output)
    model = tf.keras.Model(inputs=inputs, outputs=contact_map_output)
    return model

# --- Part 2: Load and Preprocess Your Raw Data ---
# This assumes you have already loaded your raw data for Dataset 3 into:
# X_test_3_split_raw (list of 'AUCG...' strings)
# y_test_3_split_db  (list of '((..))' strings)

print("Preprocessing raw data for Transformer model...")

# Define the vocabulary for one-hot encoding
sequence_vocab = {'A': 0, 'U': 1, 'G': 2, 'C': 3}
SEQ_LEN = 150

# One-hot encode the input sequences
X_test_one_hot = np.array([one_hot_encode_sequence(seq, sequence_vocab, SEQ_LEN) for seq in X_test_3_split_raw])

# Convert the target dot-bracket strings to contact maps
y_test_cm = np.array([dotbracket_to_contact_map(db) for db in y_test_3_split_db])

print(f"Data preprocessed successfully. Shape of X_test_one_hot: {X_test_one_hot.shape}")


# --- Part 3: Load the Trained Model ---

print("\nLoading trained Transformer model...")
transformer_model = create_transformer_model_one_hot_input()

# Build the model with the correct input shape
input_shape = (None, SEQ_LEN, len(sequence_vocab))
transformer_model.build(input_shape)

# Load the saved weights
weights_path = '/content/drive/MyDrive/RNA_Project_Models/Transformer/best_model_transformer_dataset3.keras'
transformer_model.load_weights(weights_path)

print("Model weights loaded successfully!")


# --- Part 4: Make and Visualize a Prediction ---

print("\nGenerating prediction for one test sample...")
# Get the first sample from your preprocessed test set
test_sequence_input = X_test_one_hot[0:1] # Use slicing to keep the batch dimension
ground_truth_cm = y_test_cm[0]

# Get the model's prediction (a probability map)
predicted_probability_map = transformer_model.predict(test_sequence_input)[0]

# Apply a threshold to get the final binary contact map
threshold = 0.5
predicted_contact_map = (predicted_probability_map > threshold).astype(int)

# --- Plotting the comparison ---
def plot_comparison(ground_truth_cm, predicted_cm):
    fig, axes = plt.subplots(1, 2, figsize=(12, 6))
    axes[0].imshow(ground_truth_cm, cmap='binary', origin='upper')
    axes[0].set_title('Ground Truth Contact Map', fontsize=16)
    axes[0].set_xlabel('Nucleotide Index', fontsize=12)
    axes[0].set_ylabel('Nucleotide Index', fontsize=12)
    axes[1].imshow(predicted_cm, cmap='binary', origin='upper')
    axes[1].set_title('Transformer Prediction Contact Map', fontsize=16)
    axes[1].set_xlabel('Nucleotide Index', fontsize=12)
    axes[1].set_ylabel('')
    plt.savefig('transformer_contact_map_comparison.png', dpi=300, bbox_inches='tight')
    plt.show()

plot_comparison(ground_truth_cm, predicted_contact_map)

