def get_constrained_rnafold_structure(sequence_str, constraint_structure_str):
    """
    Calls RNAfold, providing the constraint_structure_str.
    RNAfold will try to respect it but prioritize valid structure formation.
    """
    if not constraint_structure_str or len(sequence_str) != len(constraint_structure_str):
        print("INFO: Invalid or missing constraint for RNAfold. Performing unconstrained MFE folding.")
        try:
            process_uc = subprocess.Popen(
                ['RNAfold', '--noPS'],
                stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True
            )
            stdout_uc, stderr_uc = process_uc.communicate(input=f">{sequence_str}\n{sequence_str}")
            if process_uc.returncode == 0:
                lines_uc = stdout_uc.strip().split('\n')
                for line_idx in range(len(lines_uc) - 1, -1, -1):
                    if '(' in lines_uc[line_idx] or ')' in lines_uc[line_idx] or '.' in lines_uc[line_idx]:
                        if not all(c.upper() in 'AUGC' for c in lines_uc[line_idx].split(' ')[0]):
                            return lines_uc[line_idx].split(' ')[0]
                return "RNAfold_Unconstrained_Parse_Error"
            else:
                print(f"RNAfold Error (Unconstrained Fallback): {stderr_uc.strip()}")
                return "RNAfold_Unconstrained_Error"
        except Exception as e_uc:
            print(f"🔴 Exception during unconstrained RNAfold: {e_uc}")
            return "RNAfold_Exception_Error"

    try:
        rnafold_input = f">{sequence_str}\n{sequence_str}\n{constraint_structure_str}" # Sequence, then constraint

        process = subprocess.Popen(
            ['RNAfold', '--noPS'],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate(input=rnafold_input)

        if process.returncode != 0:
            print(f"RNAfold Error (with suggested constraint) for '{sequence_str[:30]}...': {stderr.strip()}")
            print("Attempting fully unconstrained RNAfold as final fallback...")
            unconstrained_input = f">{sequence_str}\n{sequence_str}"
            process_uc = subprocess.Popen(['RNAfold', '--noPS'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            stdout_uc, stderr_uc = process_uc.communicate(input=unconstrained_input)
            if process_uc.returncode == 0:
                lines_uc = stdout_uc.strip().split('\n')
                for line_idx in range(len(lines_uc) - 1, -1, -1): # Search from bottom up
                    if '(' in lines_uc[line_idx] or ')' in lines_uc[line_idx] or '.' in lines_uc[line_idx]:
                        if not all(c.upper() in 'AUGC' for c in lines_uc[line_idx].split(' ')[0]):
                             return lines_uc[line_idx].split(' ')[0]
                return "RNAfold_Final_Fallback_Parse_Error"
            return "RNAfold_Error_then_Final_Fallback_Error"

        lines = stdout.strip().split('\n')
        for line_idx in range(len(lines) -1, -1, -1): # Search from bottom up
            if '(' in lines[line_idx] or ')' in lines[line_idx] or '.' in lines[line_idx]:
                if not all(c.upper() in 'AUGC' for c in lines[line_idx].split(' ')[0]): # Avoid picking the sequence line
                    return lines[line_idx].split(' ')[0]
        return "RNAfold_Parse_Error_Structure_Line_Not_Found"
    except FileNotFoundError:
        print("🔴 ERROR: RNAfold command not found.")
        return "RNAfold_Not_Found"
    except Exception as e:
        print(f"🔴 An unexpected error occurred with RNAfold: {e}")
        return "RNAfold_Unexpected_Error"

