import os

# This function is all you need.
def visualize_prediction(true_structure, predicted_structure, title="Prediction Analysis", chunk_size=60):
    """
    Generates a detailed, color-coded, per-position comparison of a predicted
    RNA structure against the ground truth, formatted exactly like the example image.

    Args:
        true_structure (str): The ground truth dot-bracket string.
        predicted_structure (str): The dot-bracket string predicted by the model.
        title (str): A title to print at the top of the visualization.
        chunk_size (int): The number of nucleotides to display per line.
    """
    # Define ANSI color codes for terminal/notebook output
    # (These may not render correctly in all environments)
    GREEN = '\033[92m'
    RED = '\033[91m'
    RESET = '\033[0m'

    # Ensure we only compare up to the shortest length to avoid errors
    min_len = min(len(true_structure), len(predicted_structure))
    true_structure = true_structure[:min_len]
    predicted_structure = predicted_structure[:min_len]

    print(f"--- {title} ---")
    print("-" * (chunk_size * 4)) # Dynamic separator length

    # --- 1. Calculate overall statistics first ---
    correct_predictions = 0
    for i in range(min_len):
        if true_structure[i] == predicted_structure[i]:
            correct_predictions += 1

    incorrect_predictions = min_len - correct_predictions
    total_positions = min_len
    accuracy = (correct_predictions / total_positions) * 100 if total_positions > 0 else 0

    # --- 2. Iterate through the sequence in chunks ---
    for i in range(0, min_len, chunk_size):
        start = i
        end = min(i + chunk_size, min_len)

        # Prepare the four lines for this chunk
        pos_line = "Position:\t"
        gt_line = "Ground Truth:\t"
        pred_line = "Prediction:\t"
        res_line = "Result:\t\t"

        for j in range(start, end):
            # Format position numbers with spacing
            pos_line += f"{j:<4}"

            # Ground truth character
            gt_line += f"{true_structure[j]:<4}"

            # Prediction and Result characters with color
            if true_structure[j] == predicted_structure[j]:
                pred_line += f"{GREEN}{predicted_structure[j]:<4}{RESET}"
                res_line += f"{GREEN}{'✓':<4}{RESET}"
            else:
                pred_line += f"{RED}{predicted_structure[j]:<4}{RESET}"
                res_line += f"{RED}{'✗':<4}{RESET}"

        # Print the formatted block for this chunk
        print(pos_line)
        print(gt_line)
        print(pred_line)
        print(res_line)
        print() # Add a blank line for spacing

    # --- 3. Print the final summary box ---
    box_width = 25
    print("\n" + " " * ((chunk_size * 4 - box_width) // 2) + "-" * box_width)
    print(" " * ((chunk_size * 4 - box_width) // 2) + f"| {'Correct Predictions:':<25} {correct_predictions:<15} |")
    print(" " * ((chunk_size * 4 - box_width) // 2) + f"| {'Incorrect Predictions:':<25} {incorrect_predictions:<15} |")
    print(" " * ((chunk_size * 4 - box_width) // 2) + f"| {'Total Positions:':<25} {total_positions:<15} |")
    print(" " * ((chunk_size * 4 - box_width) // 2) + f"| {'-'*46} |")
    print(" " * ((chunk_size * 4 - box_width) // 2) + f"| {'Per-Nucleotide Accuracy = (Correct) / (Total)':<46} |")
    print(" " * ((chunk_size * 4 - box_width) // 2) + f"| {'Accuracy = ' f'{correct_predictions}/{total_positions} = {accuracy:.2f}%':<46} |")
    print(" " * ((chunk_size * 4 - box_width) // 2) + "-" * box_width)


