# This is a complete, self-contained script to generate the visualization.

def visualize_prediction_detailed(true_structure, predicted_structure, sequence=None, title="Prediction Analysis", chunk_size=60):
    """
    Generates a detailed, color-coded, per-position comparison of a predicted
    RNA structure against the ground truth, formatted like the example image.

    Args:
        true_structure (str): The ground truth dot-bracket string (unpadded).
        predicted_structure (str): The dot-bracket string predicted by the model (unpadded).
        sequence (str, optional): The input RNA sequence (unpadded).
        title (str): A title to print at the top of the visualization.
        chunk_size (int): The number of nucleotides to display per line.
    """
    # Define ANSI color codes for terminal/notebook output.
    # In some environments like plain Python scripts, these might not render as colors.
    GREEN = '\033[92m'
    RED = '\03g[91m'
    RESET = '\033[0m'

    # Ensure we only compare up to the shortest length to avoid errors
    min_len = min(len(true_structure), len(predicted_structure))

    print(f"--- {title} ---")
    if sequence:
        print(f"Input RNA Sequence ({len(sequence)} nt):")
        # Print sequence in chunks
        for i in range(0, len(sequence), chunk_size):
            print(sequence[i:i+chunk_size])

    print(f"\nTrue Structure ({len(true_structure)} nt):")
    for i in range(0, len(true_structure), chunk_size):
            print(true_structure[i:i+chunk_size])

    print(f"\nPrediction ({len(predicted_structure)} nt):")
    for i in range(0, len(predicted_structure), chunk_size):
            print(predicted_structure[i:i+chunk_size])

    print("-" * (chunk_size + 15)) # Dynamic separator

    # --- 1. Calculate overall statistics first ---
    correct_predictions = 0
    for i in range(min_len):
        if true_structure[i] == predicted_structure[i]:
            correct_predictions += 1

    incorrect_predictions = min_len - correct_predictions
    total_positions = min_len
    accuracy = (correct_predictions / total_positions) * 100 if total_positions > 0 else 0

    # --- 2. Iterate through the sequence in chunks to show the detailed view ---
    for i in range(0, min_len, chunk_size):
        start = i
        end = min(i + chunk_size, min_len)

        # Prepare the four lines for this chunk
        pos_line = "Position:\t"
        gt_line = "Ground Truth:\t"
        pred_line = "Prediction:\t"
        res_line = "Result:\t\t"

        for j in range(start, end):
            # Format position numbers with spacing
            pos_line += f"{j:<4}"
            gt_line += f"{true_structure[j]:<4}"

            # Prediction and Result characters with color
            if true_structure[j] == predicted_structure[j]:
                pred_line += f"{GREEN}{predicted_structure[j]:<4}{RESET}"
                res_line += f"{GREEN}{'✓':<4}{RESET}"
            else:
                pred_line += f"{RED}{predicted_structure[j]:<4}{RESET}"
                res_line += f"{RED}{'✗':<4}{RESET}"

        # Print the formatted block for this chunk
        print(pos_line)
        print(gt_line)
        print(pred_line)
        print(res_line)
        print() # Add a blank line for spacing

    # --- 3. Print the final summary box ---
    box_width = 50
    print("\n" + " " * 10 + "-" * box_width)
    print(" " * 10 + f"| {'Correct Predictions:':<25} {correct_predictions:<15} |")
    print(" " * 10 + f"| {'Incorrect Predictions:':<25} {incorrect_predictions:<15} |")
    print(" " * 10 + f"| {'Total Positions:':<25} {total_positions:<15} |")
    print(" " * 10 + f"| {'-'*46} |")
    print(" " * 10 + f"| {'Per-Nucleotide Accuracy = (Correct) / (Total)':<46} |")
    print(" " * 10 + f"| {'Accuracy = ' f'{correct_predictions}/{total_positions} = {accuracy:.2f}%':<46} |")
    print(" " * 10 + "-" * box_width)

