# Cell: FINAL DEMO v2 - Ensemble Prediction, Raw DL Metrics, & MFE Reference

import tensorflow as tf
import numpy as np
import os
import subprocess
from tensorflow.keras.preprocessing.sequence import pad_sequences

print("--- Setting up FINAL DEMO Ensemble Prediction Cell (v2) ---")

# --- CRITICAL: Ensure Global Constants from Cell 1 are Available & CORRECT ---
global_vars_needed = [
    'INT_TO_CHAR_SEQ', 'CHAR_TO_INT_SEQ', 'SEQ_CHARS',
    'INT_TO_CHAR_STRUCT', 'CHAR_TO_INT_STRUCT', 'STRUCT_CHARS',
    'EXPECTED_MAX_LEN', 'DRIVE_MODELS_PATH'
]
all_globals_present = True
for var_name in global_vars_needed:
    if var_name not in globals():
        print(f"🔴 CRITICAL ERROR: Global constant '{var_name}' from Cell 1 is MISSING.")
        all_globals_present = False
if not all_globals_present:
    print("   Please RE-RUN Cell 1 (Setup) to define these variables correctly.")
    raise NameError("Essential global constants from Cell 1 are not defined.")

PAD_CHAR_SEQ = '<PAD>'
PAD_TOKEN_SEQ_INT = CHAR_TO_INT_SEQ[PAD_CHAR_SEQ]
PAD_CHAR_STRUCT = '<PAD>'
PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT[PAD_CHAR_STRUCT]
print(f"DEBUG: PAD_TOKEN_SEQ_INT={PAD_TOKEN_SEQ_INT}, PAD_TOKEN_STRUCT_INT={PAD_TOKEN_STRUCT_INT}")


# --- !!! CRITICAL STEP: UPDATE THESE MODEL PATHS !!! ---
MODEL_PATHS_BY_GC_RANGE = {
    "low_gc":      os.path.join(DRIVE_MODELS_PATH, 'best_model_v6_dataset1.keras'), # EXAMPLE
    "mid_low_gc":  os.path.join(DRIVE_MODELS_PATH, 'best_model_v6_dataset2.keras'), # EXAMPLE
    "mid_high_gc": os.path.join(DRIVE_MODELS_PATH, 'best_model_v4_cnn_bilstm_dataset3.keras'), # EXAMPLE
    "high_gc":     os.path.join(DRIVE_MODELS_PATH, 'best_model_v2_dataset4.keras')    # EXAMPLE
}
print("Using the following specialist models for GC ranges:")
for gc_cat, path in MODEL_PATHS_BY_GC_RANGE.items():
    print(f"  {gc_cat}: {os.path.basename(path)}")
loaded_specialist_models = {}

# --- Helper Functions ---
def calculate_gc_content(sequence_str):
    if not sequence_str: return 0.0
    sequence_str_upper = sequence_str.upper()
    gc_count = sequence_str_upper.count('G') + sequence_str_upper.count('C')
    return gc_count / len(sequence_str) if len(sequence_str) > 0 else 0.0

def preprocess_single_sequence_for_dl(sequence_str, char_to_int_map, max_len, pad_value_int):
    tokenized_seq = [char_to_int_map.get(char.upper(), pad_value_int) for char in sequence_str]
    padded_seq_batch = pad_sequences([tokenized_seq], maxlen=max_len, padding='post', truncating='post', value=pad_value_int)
    return padded_seq_batch

def get_dl_model_prediction_ensemble(rna_sequence_str):
    gc_content = calculate_gc_content(rna_sequence_str)
    model_key = None
    if gc_content <= 0.25: model_key = "low_gc"
    elif gc_content <= 0.50: model_key = "mid_low_gc"
    elif gc_content <= 0.75: model_key = "mid_high_gc"
    else: model_key = "high_gc"

    # print(f"Input GC: {gc_content:.2f}, Selected model category: {model_key}") # Optional
    model_path = MODEL_PATHS_BY_GC_RANGE.get(model_key)

    if not model_path:
        print(f"🔴 No model path defined for GC category: {model_key} (GC: {gc_content:.2f}). Cannot get DL prediction.")
        return None, model_key

    if model_path not in loaded_specialist_models:
        print(f"Loading specialist DL model for '{model_key}' from: {model_path}...")
        try:
            if not os.path.exists(model_path): raise FileNotFoundError(f"Model file not found: {model_path}")
            loaded_specialist_models[model_path] = tf.keras.models.load_model(model_path)
            print(f"Model '{os.path.basename(model_path)}' loaded for GC key '{model_key}'.")
        except Exception as e:
            print(f"🔴 Failed to load DL model {model_path}: {e}")
            return None, model_key

    specialist_model = loaded_specialist_models[model_path]
    preprocessed_sequence = preprocess_single_sequence_for_dl(rna_sequence_str, CHAR_TO_INT_SEQ, EXPECTED_MAX_LEN, PAD_TOKEN_SEQ_INT)

    prediction_probs = specialist_model.predict(preprocessed_sequence, verbose=0)
    predicted_classes_int_padded = np.argmax(prediction_probs, axis=-1)[0]

    predicted_structure_chars_padded_list = []
    for token_val in predicted_classes_int_padded:
        token_int = int(token_val)
        char_representation = INT_TO_CHAR_STRUCT.get(token_int, "<?>") # Simpler error char
        predicted_structure_chars_padded_list.append(char_representation)
    predicted_structure_chars_padded = "".join(predicted_structure_chars_padded_list)

    final_dl_predicted_structure = predicted_structure_chars_padded[:len(rna_sequence_str)] # Trim to original RNA length
    return final_dl_predicted_structure, model_key


def get_mfe_rnafold_structure(sequence_str):
    if not sequence_str: return "RNAfold_Input_Error_Empty_Seq"
    # print(f"Getting MFE structure from RNAfold for: {sequence_str[:30]}...") # Optional
    try:
        rnafold_input = f">mfe_sequence\n{sequence_str}"
        process = subprocess.Popen(
            ['RNAfold', '--noPS'],
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True
        )
        stdout, stderr = process.communicate(input=rnafold_input, timeout=30)

        if process.returncode == 0 and stdout:
            lines = stdout.strip().split('\n')
            for line_idx in range(len(lines) - 1, -1, -1):
                potential_struct = lines[line_idx].split(' ')[0]
                if len(potential_struct) == len(sequence_str) and all(c in '.()[]{}<>' for c in potential_struct):
                    if potential_struct.count('(') == potential_struct.count(')'):
                        return potential_struct
            return "RNAfold_MFE_Parse_Error"
        else:
            print(f"RNAfold MFE Error (Code: {process.returncode}): {stderr.strip()}")
            return "RNAfold_MFE_Execution_Error"
    except Exception as e:
        print(f"🔴 Exception during MFE RNAfold: {e}")
        return "RNAfold_MFE_Exception"


# --- Main Prediction and Display Loop ---
DATASET_ID_FOR_EXAMPLES = 3
NUM_EXAMPLES_TO_SHOW = 5
print(f"\n--- DL Ensemble Raw Prediction vs. True Structure (Examples from Dataset {DATASET_ID_FOR_EXAMPLES} Test Set) ---")

X_test_examples = globals().get(f'X_test_{DATASET_ID_FOR_EXAMPLES}_split')
y_test_examples_int = globals().get(f'y_test_{DATASET_ID_FOR_EXAMPLES}_split')

if X_test_examples is None or y_test_examples_int is None:
    print(f"🔴 Test data for Dataset {DATASET_ID_FOR_EXAMPLES} not loaded (expected X_test_{DATASET_ID_FOR_EXAMPLES}_split).")
else:
    sample_indices_to_show = np.arange(min(NUM_EXAMPLES_TO_SHOW, len(X_test_examples)))

    for k_idx, sample_idx in enumerate(sample_indices_to_show):
        print(f"\n--- Sample {k_idx+1} (Index {sample_idx} from Test Set {DATASET_ID_FOR_EXAMPLES}) ---")

        rna_seq_int_padded = X_test_examples[sample_idx]
        true_struct_int_padded = y_test_examples_int[sample_idx]

        # Reconstruct unpadded RNA sequence and true structure strings
        rna_sequence_str_unpadded_list = []
        for token_val_seq in rna_seq_int_padded:
            token_int_seq = int(token_val_seq)
            if token_int_seq == PAD_TOKEN_SEQ_INT: break
            rna_sequence_str_unpadded_list.append(INT_TO_CHAR_SEQ.get(token_int_seq, "<?>"))
        rna_sequence_str_unpadded = "".join(rna_sequence_str_unpadded_list)

        true_structure_str_unpadded_list = []
        for token_val_struct in true_struct_int_padded:
            token_int_struct = int(token_val_struct)
            if token_int_struct == PAD_TOKEN_STRUCT_INT: break
            true_structure_str_unpadded_list.append(INT_TO_CHAR_STRUCT.get(token_int_struct, "<?>"))
        true_structure_str_unpadded = "".join(true_structure_str_unpadded_list)
        true_structure_str_unpadded = true_structure_str_unpadded[:len(rna_sequence_str_unpadded)]

        print(f"Input RNA Sequence ({len(rna_sequence_str_unpadded)} nt):")
        print(f"  {rna_sequence_str_unpadded}")
        print(f"True Structure     ({len(true_structure_str_unpadded)} nt):")
        print(f"  {true_structure_str_unpadded}")

        if not rna_sequence_str_unpadded or "<?>" in rna_sequence_str_unpadded:
            print("🔴 Reconstructed RNA sequence is invalid. Skipping this sample's predictions.")
            continue
        if not true_structure_str_unpadded or "<?>" in true_structure_str_unpadded:
            print("🔴 Reconstructed True Structure is invalid. Comparisons may be unreliable.")

        # 1. Get DL Model Ensemble's Raw Prediction
        dl_raw_prediction_str, used_model_key = get_dl_model_prediction_ensemble(rna_sequence_str_unpadded)

        if dl_raw_prediction_str and "<?>" not in dl_raw_prediction_str:
            open_br_dl = dl_raw_prediction_str.count('(')
            close_br_dl = dl_raw_prediction_str.count(')')
            balance_status_dl = "Balanced" if open_br_dl == close_br_dl else f"UNBALANCED (Open:{open_br_dl}, Close:{close_br_dl})"
            print(f"DL Raw Prediction  (using '{used_model_key}', {balance_status_dl}):")
            print(f"  {dl_raw_prediction_str}")

            # --- Calculate "Correctly Predicted Paired States / Total Nucleotides" for RAW DL Prediction ---
            correctly_predicted_open_dl = 0
            correctly_predicted_close_dl = 0

            compare_len = min(len(true_structure_str_unpadded), len(dl_raw_prediction_str))
            if compare_len != len(rna_sequence_str_unpadded):
                 print(f"  Warning: Length mismatch for paired state calculation (True: {len(true_structure_str_unpadded)}, DL_Raw: {len(dl_raw_prediction_str)}). Comparing up to {compare_len}nt.")


            for k_bp in range(compare_len):
                true_char = true_structure_str_unpadded[k_bp]
                pred_char = dl_raw_prediction_str[k_bp]

                if true_char == '(' and pred_char == '(':
                    correctly_predicted_open_dl += 1
                elif true_char == ')' and pred_char == ')':
                    correctly_predicted_close_dl += 1

            num_correct_bp_chars_dl = correctly_predicted_open_dl + correctly_predicted_close_dl
            total_nucleotides_in_sequence = len(rna_sequence_str_unpadded)
            if total_nucleotides_in_sequence > 0:
                accuracy_of_bp_chars_vs_total_len_dl = num_correct_bp_chars_dl / total_nucleotides_in_sequence
                print(f"  Correctly Predicted Paired Chars / Total Nucleotides (Raw DL): {num_correct_bp_chars_dl}/{total_nucleotides_in_sequence} ({accuracy_of_bp_chars_vs_total_len_dl:.2%})")
            else:
                print("  Cannot calculate 'Correctly Predicted Paired Chars / Total Nucleotides' (Raw DL): zero length sequence.")

        elif dl_raw_prediction_str and "<?>" in dl_raw_prediction_str:
             print(f"DL Raw Prediction  (using '{used_model_key}' model) CONTAINS ERRORS from INT_TO_CHAR_STRUCT lookup: {dl_raw_prediction_str}")
        else:
            print(f"DL Model Ensemble prediction for this sample failed or returned None.")

        # 2. Get standard MFE prediction from RNAfold for reference

        # mfe_structure_str = get_mfe_rnafold_structure(rna_sequence_str_unpadded)
        # if "Error" not in mfe_structure_str and "Not_Found" not in mfe_structure_str and mfe_structure_str is not None:
