        #     compare_len_mfe = min(len(true_structure_str_unpadded), len(mfe_structure_str))
        #     if compare_len_mfe > 0:
        #         for k_comp in range(compare_len_mfe):
        #             if true_structure_str_unpadded[k_comp] != mfe_structure_str[k_comp]:
