# --- Helper Function: Calculate GC Content ---
def calculate_gc_content(sequence_str):
    if not sequence_str: return 0.0
    sequence_str_upper = sequence_str.upper()
    gc_count = sequence_str_upper.count('G') + sequence_str_upper.count('C')
    return gc_count / len(sequence_str) if len(sequence_str) > 0 else 0.0

# --- Helper Function: Preprocess a Single Sequence for DL Model ---
def preprocess_single_sequence_for_dl(sequence_str, char_to_int_map, max_len, pad_value_int):
    tokenized_seq = [char_to_int_map.get(char.upper(), pad_value_int) for char in sequence_str]
    padded_seq_batch = pad_sequences([tokenized_seq], maxlen=max_len, padding='post', truncating='post', value=pad_value_int)
    return padded_seq_batch

# --- Helper Function: Get DL Model Prediction using Ensemble ---
def get_dl_model_prediction_ensemble(rna_sequence_str):
    gc_content = calculate_gc_content(rna_sequence_str)
    model_key = None
    if gc_content <= 0.25: model_key = "low_gc"
    elif gc_content <= 0.50: model_key = "mid_low_gc"
    elif gc_content <= 0.75: model_key = "mid_high_gc"
    else: model_key = "high_gc"

    # print(f"Input GC: {gc_content:.2f}, Selected model category: {model_key}") # Optional detailed print
    model_path = MODEL_PATHS_BY_GC_RANGE.get(model_key)

    if not model_path:
        print(f"🔴 No model path defined for GC category: {model_key} (GC: {gc_content:.2f}). Cannot get DL prediction.")
        return None, model_key

    if model_path not in loaded_specialist_models:
        print(f"Loading specialist DL model for '{model_key}' from: {model_path}...")
        try:
            if not os.path.exists(model_path):
                raise FileNotFoundError(f"Model file not found: {model_path}")
            loaded_specialist_models[model_path] = tf.keras.models.load_model(model_path)
            print(f"Model '{os.path.basename(model_path)}' loaded for GC key '{model_key}'.")
        except Exception as e:
            print(f"🔴 Failed to load DL model {model_path}: {e}")
            return None, model_key

    specialist_model = loaded_specialist_models[model_path]
    preprocessed_sequence = preprocess_single_sequence_for_dl(rna_sequence_str, CHAR_TO_INT_SEQ, EXPECTED_MAX_LEN, PAD_TOKEN_SEQ_INT)

    prediction_probs = specialist_model.predict(preprocessed_sequence, verbose=0)
    predicted_classes_int_padded = np.argmax(prediction_probs, axis=-1)[0]

    predicted_structure_chars_padded_list = []
    for token_val in predicted_classes_int_padded: # Iterate through the 1D numpy array
        token_int = int(token_val) # Convert numpy int (e.g., np.int32, np.int64) to Python int
        char_representation = INT_TO_CHAR_STRUCT.get(token_int, "<?>DL") # Use distinct error marker
        predicted_structure_chars_padded_list.append(char_representation)
    predicted_structure_chars_padded = "".join(predicted_structure_chars_padded_list)

    # Trim DL prediction to original RNA sequence length
    final_dl_predicted_structure = predicted_structure_chars_padded[:len(rna_sequence_str)]
    return final_dl_predicted_structure, model_key


# --- Helper Function: Get Unconstrained MFE Structure from RNAfold ---
def get_mfe_rnafold_structure(sequence_str):
    """Calls RNAfold for unconstrained MFE prediction."""
    if not sequence_str:
        # print("INFO (get_mfe_rnafold_structure): Empty sequence provided.")
        return "RNAfold_Input_Error_Empty_Seq"
    # print(f"Getting MFE structure from RNAfold for: {sequence_str[:30]}...") # Optional detailed print
    try:
        rnafold_input = f">mfe_sequence\n{sequence_str}"
        process = subprocess.Popen(
            ['RNAfold', '--noPS'], # Standard MFE prediction
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True
        )
        stdout, stderr = process.communicate(input=rnafold_input, timeout=30) # Added timeout

        if process.returncode == 0 and stdout:
            lines = stdout.strip().split('\n')
            for line_idx in range(len(lines) - 1, -1, -1): # Search from bottom up for safety
                potential_struct = lines[line_idx].split(' ')[0]
                if len(potential_struct) == len(sequence_str) and all(c in '.()[]{}<>' for c in potential_struct):
                    if potential_struct.count('(') == potential_struct.count(')'): # Check balance
                        return potential_struct
            return "RNAfold_MFE_Parse_Error"
        else:
            print(f"RNAfold MFE Error (Return Code: {process.returncode}): {stderr.strip()}")
            return "RNAfold_MFE_Execution_Error"
    except subprocess.TimeoutExpired:
        print("🔴 RNAfold MFE prediction timed out.")
        return "RNAfold_MFE_Timeout_Error"
    except FileNotFoundError:
        print("🔴 ERROR: RNAfold command not found. Make sure ViennaRNA is installed and in PATH.")
        return "RNAfold_Not_Found"
    except Exception as e:
        print(f"🔴 Exception during MFE RNAfold: {e}")
        return "RNAfold_MFE_Exception"


