import numpy as np
import matplotlib.pyplot as plt

# --- Step 1: Define the utility functions ---
def dotbracket_to_contact_map(db_string):
    n = len(db_string)
    contact_map = np.zeros((n, n), dtype=int)
    stack = []
    for i, char in enumerate(db_string):
        if char == '(': stack.append(i)
        elif char == ')':
            if len(stack) > 0:
                j = stack.pop(); contact_map[i, j] = 1; contact_map[j, i] = 1
    return contact_map

def plot_contact_map(contact_map, title="RNA Contact Map"):
    plt.figure(figsize=(6, 6))
    plt.imshow(contact_map, cmap='binary', origin='upper')
    plt.title(title, fontsize=16)
    plt.xlabel("Nucleotide Index", fontsize=12)
    plt.ylabel("Nucleotide Index", fontsize=12)
    filename = title.replace(" ", "_").lower() + ".png"
    plt.savefig(filename, dpi=300, bbox_inches='tight')
    plt.show()

