import tensorflow as tf
import numpy as np
import os
import subprocess
from tensorflow.keras.preprocessing.sequence import pad_sequences
from sklearn.metrics import classification_report, confusion_matrix, ConfusionMatrixDisplay
import pandas as pd

print("--- Setting up FINAL DEMO Ensemble Prediction Cell (v3 with Final Summary) ---")

# --- CRITICAL: Ensure Global Constants from Cell 1 are Available & CORRECT ---
global_vars_needed = [
    'INT_TO_CHAR_SEQ', 'CHAR_TO_INT_SEQ', 'SEQ_CHARS',
    'INT_TO_CHAR_STRUCT', 'CHAR_TO_INT_STRUCT', 'STRUCT_CHARS',
    'EXPECTED_MAX_LEN', 'DRIVE_MODELS_PATH'
]
if not all(var in globals() for var in global_vars_needed):
    raise NameError("Essential global constants from Cell 1 are not defined. Please re-run Cell 1.")
PAD_CHAR_SEQ = '<PAD>'; PAD_TOKEN_SEQ_INT = CHAR_TO_INT_SEQ[PAD_CHAR_SEQ]
PAD_CHAR_STRUCT = '<PAD>'; PAD_TOKEN_STRUCT_INT = CHAR_TO_INT_STRUCT[PAD_CHAR_STRUCT]

# --- !!! CRITICAL STEP: UPDATE THESE MODEL PATHS !!! ---
MODEL_PATHS_BY_GC_RANGE = {
    "low_gc":      os.path.join(DRIVE_MODELS_PATH, 'best_model_v6_dataset1.keras'),
    "mid_low_gc":  os.path.join(DRIVE_MODELS_PATH, 'best_model_v6_dataset2.keras'),
    "mid_high_gc": os.path.join(DRIVE_MODELS_PATH, 'best_model_v4_cnn_bilstm_dataset3.keras'),
    "high_gc":     os.path.join(DRIVE_MODELS_PATH, 'best_model_v2_dataset4.keras')
}
print("Using the following specialist models for GC ranges:")
for gc_cat, path in MODEL_PATHS_BY_GC_RANGE.items():
    print(f"  {gc_cat}: {os.path.basename(path)}")
loaded_specialist_models = {}

# --- Helper Functions ---
def calculate_gc_content(sequence_str):
    if not sequence_str: return 0.0
    sequence_str_upper = sequence_str.upper()
    gc_count = sequence_str_upper.count('G') + sequence_str_upper.count('C')
    return gc_count / len(sequence_str) if len(sequence_str) > 0 else 0.0

def preprocess_single_sequence_for_dl(sequence_str, char_to_int_map, max_len, pad_value_int):
    tokenized_seq = [char_to_int_map.get(char.upper(), pad_value_int) for char in sequence_str]
    return pad_sequences([tokenized_seq], maxlen=max_len, padding='post', truncating='post', value=pad_value_int)

def get_dl_model_prediction_ensemble(rna_sequence_str):
    gc_content = calculate_gc_content(rna_sequence_str)
    model_key = None
    if gc_content <= 0.25: model_key = "low_gc"
    elif gc_content <= 0.50: model_key = "mid_low_gc"
    elif gc_content <= 0.75: model_key = "mid_high_gc"
    else: model_key = "high_gc"

    model_path = MODEL_PATHS_BY_GC_RANGE.get(model_key)
    if not model_path:
        print(f"🔴 No model path defined for GC key: {model_key} (GC: {gc_content:.2f}).")
        return None, model_key

    if model_path not in loaded_specialist_models:
        print(f"Loading specialist DL model for '{model_key}' from: {model_path}...")
        # THIS IS THE BLOCK WHERE THE ERROR LIKELY IS
        try:
            if not os.path.exists(model_path):
                raise FileNotFoundError(f"Model file not found: {model_path}")
            loaded_specialist_models[model_path] = tf.keras.models.load_model(model_path)
            print(f"Model '{os.path.basename(model_path)}' loaded.")
        except Exception as e: # This 'except' must align with 'try'
            print(f"🔴 Failed to load DL model {model_path}: {e}")
            return None, model_key

    specialist_model = loaded_specialist_models[model_path]
    preprocessed_sequence = preprocess_single_sequence_for_dl(rna_sequence_str, CHAR_TO_INT_SEQ, EXPECTED_MAX_LEN, PAD_TOKEN_SEQ_INT)

    prediction_probs = specialist_model.predict(preprocessed_sequence, verbose=0)
    predicted_classes_int_padded = np.argmax(prediction_probs, axis=-1)[0]

    predicted_structure_chars_padded_list = [INT_TO_CHAR_STRUCT.get(int(token_val), "<?>") for token_val in predicted_classes_int_padded]
    predicted_structure_chars_padded = "".join(predicted_structure_chars_padded_list)
    return predicted_structure_chars_padded[:len(rna_sequence_str)], model_key


# --- Main Prediction and Display Loop ---
DATASET_ID_FOR_EXAMPLES = 3
NUM_EXAMPLES_TO_SHOW = 100

print(f"\n--- DL Ensemble Raw Prediction vs. True Structure (Examples from Dataset {DATASET_ID_FOR_EXAMPLES} Test Set) ---")

X_test_examples = globals().get(f'X_test_{DATASET_ID_FOR_EXAMPLES}_split')
y_test_examples_int = globals().get(f'y_test_{DATASET_ID_FOR_EXAMPLES}_split')

# Initialize lists to aggregate results for final summary
all_true_flat_for_summary = []
all_pred_flat_for_summary = []

if X_test_examples is None or y_test_examples_int is None:
    print(f"🔴 Test data for Dataset {DATASET_ID_FOR_EXAMPLES} not loaded.")
else:
    num_samples_to_process = min(NUM_EXAMPLES_TO_SHOW, len(X_test_examples))
    sample_indices_to_process = np.arange(num_samples_to_process)

    for k_idx, sample_idx in enumerate(sample_indices_to_process):
        if (k_idx + 1) % 20 == 0 or k_idx == 0: # Print progress less frequently
            print(f"\n--- Processing Sample {k_idx+1}/{num_samples_to_process} (Index {sample_idx}) ---")

        rna_seq_int_padded = X_test_examples[sample_idx]
        true_struct_int_padded = y_test_examples_int[sample_idx]

        # String Reconstruction
        rna_sequence_str_unpadded = "".join([INT_TO_CHAR_SEQ.get(int(t), "?") for t in rna_seq_int_padded if int(t) != PAD_TOKEN_SEQ_INT])
        true_structure_str_unpadded = "".join([INT_TO_CHAR_STRUCT.get(int(t), "?") for t in true_struct_int_padded if int(t) != PAD_TOKEN_STRUCT_INT])
        true_structure_str_unpadded = true_structure_str_unpadded[:len(rna_sequence_str_unpadded)]

        if not rna_sequence_str_unpadded or "?" in rna_sequence_str_unpadded:
            continue

        # Get DL Model Ensemble's Raw Prediction
        dl_raw_prediction_str, used_model_key = get_dl_model_prediction_ensemble(rna_sequence_str_unpadded)

        if dl_raw_prediction_str and "?" not in dl_raw_prediction_str:
            # Aggregate results for the final summary
            true_struct_int_unpadded = [CHAR_TO_INT_STRUCT.get(c, -1) for c in true_structure_str_unpadded]
            pred_struct_int_unpadded = [CHAR_TO_INT_STRUCT.get(c, -1) for c in dl_raw_prediction_str]
            all_true_flat_for_summary.extend(true_struct_int_unpadded)
            all_pred_flat_for_summary.extend(pred_struct_int_unpadded)

    print("\n--- Individual Sample Processing Finished ---")

# --- FINAL SUMMARY SECTION (AFTER THE LOOP) ---
if not all_true_flat_for_summary:
    print("\n🔴 No valid predictions were aggregated. Cannot generate final summary.")
else:
    print(f"\n\n--- Overall Summary for {len(all_true_flat_for_summary)} characters from {num_samples_to_process} samples ---")

    report_chars = ['.', '(', ')']
    report_ints = [CHAR_TO_INT_STRUCT[c] for c in report_chars]

    # Confusion Matrix Table
    print("\nConfusion Matrix Table (Rows=True, Columns=Predicted):")
    cm_array = confusion_matrix(all_true_flat_for_summary, all_pred_flat_for_summary, labels=report_ints)
    cm_df = pd.DataFrame(cm_array, index=[f"True: {c}" for c in report_chars], columns=[f"Pred: {c}" for c in report_chars])
    print(cm_df)

    # Overall Accuracy
    total_correct = np.sum(np.array(all_true_flat_for_summary) == np.array(all_pred_flat_for_summary))
    total_compared = len(all_true_flat_for_summary)
    overall_accuracy = total_correct / total_compared if total_compared > 0 else 0
    print(f"\nTotal Correctly Predicted Characters: {total_correct} / {total_compared} ({overall_accuracy:.2%})")

    # Classification Report
    print("\nOverall Classification Report (excluding padding):")
    print(classification_report(all_true_flat_for_summary, all_pred_flat_for_summary, labels=report_ints, target_names=report_chars, zero_division=0))

    # Visual Confusion Matrix
    print("\nVisual Confusion Matrix Plot:")
    disp = ConfusionMatrixDisplay(confusion_matrix=cm_array, display_labels=report_chars)
    disp.plot(cmap=plt.cm.Greens)
    plt.title(f"Overall Confusion Matrix\n(Ensemble Predictions on {num_samples_to_process} samples from DS{DATASET_ID_FOR_EXAMPLES})")
    plt.show()

