# You must have this function defined in a cell
def create_bigru_model(embedding_dim=224, gru_units=64, dropout_rate_1=0.2, dropout_rate_2=0.4, vocab_size=5, num_classes=4):
    # This architecture must EXACTLY match the one you used for training M5
    model = tf.keras.Sequential([
        tf.keras.layers.Embedding(input_dim=vocab_size, output_dim=embedding_dim, mask_zero=True),
        tf.keras.layers.Dropout(dropout_rate_1),
        tf.keras.layers.Bidirectional(tf.keras.layers.GRU(gru_units, return_sequences=True)),
        tf.keras.layers.Dropout(dropout_rate_2),
        tf.keras.layers.TimeDistributed(tf.keras.layers.Dense(num_classes, activation='softmax'))
    ], name="RNA_Predictor_BiGRU_Tuned")
    return model

# The model outputs logits (raw numerical scores) for each position
predicted_logits = model.predict(test_sequence_processed)

import numpy as np

# You need your vocabulary mapping (the reverse of what you used for encoding)
# It should look something like this:
idx_to_char = {0: '.', 1: '(', 2: ')', 3: '<PAD>'}

# Find the index of the highest logit for each position in the sequence
predicted_indices = np.argmax(predicted_logits, axis=-1)[0] # [0] to remove batch dim

# Build the predicted string, ignoring padding
predicted_db_string = ""
for idx in predicted_indices:
    char = idx_to_char.get(idx)
    if char != '<PAD>':
        predicted_db_string += char

print(f"Ground Truth String:  {ground_truth_db_string}")
print(f"Predicted String:     {predicted_db_string}")

